window.QUESTION_BANK = [{"id":"base-001","question":"The United Nations was founded on:","options":["24 October 1945","26 June 1945","1 January 1942","10 December 1948"],"answer":0,"explanation":"The UN was established on 24 October 1945 after WWII, to prevent future wars and promote international cooperation.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-002","question":"How many member states does the UN currently have?","options":["180","191","193","197"],"answer":2,"explanation":"The UN has 193 member states — every recognized country except the Vatican (Holy See).","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-003","question":"Which of the following is NOT one of the six official UN languages?","options":["Arabic","Portuguese","Russian","Spanish"],"answer":1,"explanation":"The six official UN languages are Arabic, Chinese, English, French, Russian, and Spanish. Portuguese is not included.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-004","question":"Which country does NOT hold a permanent seat on the UN Security Council?","options":["France","Germany","Russia","United Kingdom"],"answer":1,"explanation":"The P5 are China, France, Russia, the United Kingdom, and the United States. Germany is not a permanent member.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-005","question":"How many elected non-permanent seats are on the UN Security Council?","options":["5","8","10","15"],"answer":2,"explanation":"The UNSC has 10 elected non-permanent seats, serving 2-year terms, in addition to the 5 permanent members.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-006","question":"Who is the current UN Secretary-General (as of March 2026)?","options":["Ban Ki-moon","Kofi Annan","Antonio Guterres","Tedros Adhanom"],"answer":2,"explanation":"Antonio Guterres of Portugal is serving his second term, which ends 31 December 2026.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-007","question":"Which UN agency is responsible for refugees and displaced persons?","options":["UNICEF","UNHCR","UNDP","FAO"],"answer":1,"explanation":"UNHCR (UN High Commissioner for Refugees) handles refugees and displaced persons.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-008","question":"Which UN agency is primarily responsible for food security?","options":["UNEP","WHO","FAO","UNESCO"],"answer":2,"explanation":"FAO (Food and Agriculture Organization) is responsible for food security.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-009","question":"How many Sustainable Development Goals (SDGs) are there?","options":["10","15","17","20"],"answer":2,"explanation":"There are 17 SDGs, adopted by 193 countries in 2015, aimed at a better world by 2030.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-010","question":"What is the SDG target year?","options":["2025","2030","2035","2050"],"answer":1,"explanation":"All 17 SDGs are aimed at achieving a better world by the year 2030.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-011","question":"According to the SDG Report 2025, what percentage of SDGs are on track?","options":["18%","35%","50%","72%"],"answer":0,"explanation":"Only 18% of SDGs are on track; roughly half are progressing too slowly or regressing.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-012","question":"The Universal Declaration of Human Rights was adopted on:","options":["24 October 1945","10 December 1948","1 January 1950","26 June 1945"],"answer":1,"explanation":"The UDHR was adopted by the UN General Assembly on 10 December 1948.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-013","question":"How many articles does the UDHR contain?","options":["20","25","30","35"],"answer":2,"explanation":"The UDHR has 30 articles covering civil, political, economic, social, and cultural rights.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-014","question":"UDHR Article 5 protects against:","options":["Arbitrary arrest","Torture and degrading treatment","Right to asylum","Forced labor"],"answer":1,"explanation":"Article 5 states that no one shall be subjected to torture or to cruel, inhuman, or degrading treatment or punishment.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-015","question":"NATO was founded in:","options":["1945","1947","1949","1955"],"answer":2,"explanation":"NATO (North Atlantic Treaty Organization) was founded on 4 April 1949 to deter Soviet aggression.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-016","question":"Which country most recently joined NATO?","options":["Ukraine","Finland","Sweden","Georgia"],"answer":2,"explanation":"Sweden joined NATO on 7 March 2024, becoming the 32nd member. Finland joined in April 2023.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-017","question":"What does NATO's Article 5 state?","options":["Members must increase defense spending to 2% GDP","An attack on one member is an attack on all","Members cannot join other military alliances","Nuclear weapons are only controlled by the USA"],"answer":1,"explanation":"Article 5 is NATO's collective defense clause: an armed attack against one member is considered an attack against all members.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-018","question":"How many member countries does NATO currently have?","options":["28","30","32","35"],"answer":2,"explanation":"After Sweden joined in March 2024, NATO has 32 member countries.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-019","question":"The current WTO Director-General is:","options":["Roberto Azevedo","Pascal Lamy","Ngozi Okonjo-Iweala","Mark Rutte"],"answer":2,"explanation":"Dr. Ngozi Okonjo-Iweala (Nigeria/USA) has been Director-General since 2021 — the first woman and first African to hold the post.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-020","question":"Which country is a member of OPEC+, but NOT a member of OPEC itself?","options":["Saudi Arabia","Iran","Russia","Nigeria"],"answer":2,"explanation":"Russia is part of OPEC+ but is not a member of OPEC itself.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-021","question":"How many countries are currently OPEC members?","options":["10","12","14","15"],"answer":1,"explanation":"OPEC has 12 current members: Saudi Arabia, Iran, Iraq, Kuwait, UAE, Venezuela, Libya, Nigeria, Algeria, Republic of Congo, Equatorial Guinea, and Gabon.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-022","question":"The G7 2026 Chair is:","options":["Canada","South Africa","France","United States"],"answer":2,"explanation":"France chairs the G7 in 2026, with the summit scheduled at Evian, 15-17 June 2026.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-023","question":"Which country chairs the G20 in 2025?","options":["India","Brazil","South Africa","Canada"],"answer":2,"explanation":"South Africa chaired the G20 in 2025.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-024","question":"Which country is a member of the G7 but NOT the G20?","options":["Canada","Italy","France","All G7 members are in G20"],"answer":3,"explanation":"All G7 members (USA, UK, Canada, France, Germany, Italy, Japan + EU) are also represented in the G20.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-025","question":"Who is the current Prime Minister of the United Kingdom?","options":["Boris Johnson","Rishi Sunak","Keir Starmer","Liz Truss"],"answer":2,"explanation":"Keir Starmer (Labour) won the July 2024 election in a landslide — Labour's best result in 17 years.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-026","question":"Who is Germany's current Chancellor?","options":["Olaf Scholz","Angela Merkel","Friedrich Merz","Annalena Baerbock"],"answer":2,"explanation":"Friedrich Merz (CDU/CSU) became Chancellor in 2025 after Olaf Scholz lost the election.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-027","question":"Who is the current NATO Secretary-General?","options":["Jens Stoltenberg","Mark Rutte","Anders Rasmussen","Antonio Guterres"],"answer":1,"explanation":"Mark Rutte (Netherlands) became NATO Secretary-General in October 2024, succeeding Jens Stoltenberg.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-028","question":"Who leads the WHO?","options":["Antonio Guterres","Kristalina Georgieva","Tedros Adhanom Ghebreyesus","Ngozi Okonjo-Iweala"],"answer":2,"explanation":"Tedros Adhanom Ghebreyesus of Ethiopia has been WHO Director-General since 2017.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-029","question":"Who leads the IMF?","options":["Christine Lagarde","Kristalina Georgieva","Janet Yellen","Ursula von der Leyen"],"answer":1,"explanation":"Kristalina Georgieva of Bulgaria has been IMF Managing Director since 2019.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-030","question":"Donald Trump was inaugurated for his second term on:","options":["20 January 2025","1 January 2025","20 November 2024","6 January 2025"],"answer":0,"explanation":"Trump was inaugurated for his second presidential term on 20 January 2025.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-031","question":"India's Prime Minister Narendra Modi won his third term in:","options":["March 2024","May 2024","August 2024","November 2024"],"answer":1,"explanation":"Modi won a third term in May 2024, but the BJP lost its outright majority and now depends on coalition partners.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-032","question":"Japan's current Prime Minister is:","options":["Fumio Kishida","Yoshihide Suga","Sanae Takaichi","Taro Aso"],"answer":2,"explanation":"Sanae Takaichi became Japan’s prime minister in October 2025 and remained in office in 2026; this answer refreshes the older source key.","source":"เอกสารชุดฝึก 200 ข้อ; ปรับข้อมูลผู้นำญี่ปุ่นถึง ต.ค. 2026"},{"id":"base-033","question":"The 2023 Turkey-Syria earthquake had a magnitude of:","options":["M6.5","M7.2","M7.8","M8.5"],"answer":2,"explanation":"The February 2023 Turkey-Syria earthquake was M7.8 — the worst disaster in Turkey in 100 years, killing 57,000+ people.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-034","question":"Hamas attacked Israel on:","options":["7 September 2023","7 October 2023","17 October 2023","7 November 2023"],"answer":1,"explanation":"On 7 October 2023, Hamas attacked Israel, killing approximately 1,200 people and taking 250+ hostage, triggering the Gaza War.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-035","question":"COP28 was held in:","options":["Glasgow","Sharm el-Sheikh","Dubai","Baku"],"answer":2,"explanation":"COP28 was held in Dubai, UAE in 2023 and produced the first-ever agreement to 'transition away from fossil fuels.'","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-036","question":"COP29 was held in:","options":["Dubai","Baku","Belem","Cairo"],"answer":1,"explanation":"COP29 was held in Baku, Azerbaijan in 2024, where the NCQG on climate finance was agreed.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-037","question":"COP30 was held in:","options":["Nairobi","Sydney","Belem, Brazil","Riyadh"],"answer":2,"explanation":"COP30 was held in Belem, Brazil in 2025, hosted in the Amazon and focused on fossil-fuel phaseout and climate finance.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-038","question":"The 2024 Paris Olympics final gold medal count showed:","options":["USA 45, China 38","USA 40, China 40","USA 38, China 42","USA 50, China 35"],"answer":1,"explanation":"At Paris 2024, both the USA and China won 40 gold medals each. The USA led in total medals 126-91.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-039","question":"Which country won the 2022 FIFA World Cup?","options":["France","Brazil","Germany","Argentina"],"answer":3,"explanation":"Argentina won the 2022 FIFA World Cup in Qatar — widely regarded as Lionel Messi's crowning achievement.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-040","question":"The 2026 FIFA World Cup will be co-hosted by:","options":["Spain, Portugal, Morocco","USA, Canada, Mexico","Brazil, Argentina, Chile","Germany, France, Netherlands"],"answer":1,"explanation":"The 2026 World Cup will be co-hosted by USA, Mexico, and Canada — the first World Cup with three host countries. It expands to 48 teams.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-041","question":"BRICS invited which countries to join at its 2023 Johannesburg Summit?","options":["Turkey, Egypt, Nigeria","Saudi Arabia, Iran, UAE, Argentina, Egypt, Ethiopia","India, China, Brazil, South Africa","Russia, China, Pakistan, Iran"],"answer":1,"explanation":"At the 2023 Johannesburg Summit, BRICS invited Saudi Arabia, Iran, UAE, Argentina, Egypt, and Ethiopia (though Argentina later withdrew).","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-042","question":"The Myanmar earthquake of March 2025 had a magnitude of:","options":["M6.8","M7.2","M7.7","M8.0"],"answer":2,"explanation":"The Myanmar M7.7 earthquake struck near Sagaing on 28 March 2025, killing 5,456 people — the worst quake of 2025.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-043","question":"The Kamchatka earthquake of July 2025 had a magnitude of:","options":["M7.8","M8.2","M8.5","M8.8"],"answer":3,"explanation":"The Kamchatka earthquake on 29 July 2025 was M8.8 — the largest since 2021 — triggering Pacific-wide tsunami warnings.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-044","question":"Timor-Leste became ASEAN's 11th member state on:","options":["26 October 2024","26 October 2025","1 January 2026","15 November 2025"],"answer":1,"explanation":"Timor-Leste became ASEAN's 11th member state on 26 October 2025, at the 47th Summit in Kuala Lumpur.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-045","question":"The 2025 Nobel Peace Prize was awarded to:","options":["Nihon Hidankyo","Narges Mohammadi","Maria Corina Machado","Ales Bialiatski"],"answer":2,"explanation":"Maria Corina Machado of Venezuela won the 2025 Nobel Peace Prize for her relentless struggle for democracy.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-046","question":"The 2024 Nobel Peace Prize was awarded to:","options":["Nihon Hidankyo","Narges Mohammadi","Maria Corina Machado","Ales Bialiatski"],"answer":0,"explanation":"Nihon Hidankyo — Japan's Hiroshima/Nagasaki survivor organisation — won the 2024 Nobel Peace Prize for campaigns for a nuclear-free world.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-047","question":"Which country won the 2018 FIFA World Cup?","options":["Brazil","Germany","France","Croatia"],"answer":2,"explanation":"France won the 2018 FIFA World Cup, held in Russia.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-048","question":"Trump's withdrawal of the USA from UNFCCC happened in:","options":["2017","2021","January 2026","March 2025"],"answer":2,"explanation":"In January 2026, Trump withdrew the U.S. from UNFCCC — a historic first, more consequential than leaving the Paris Agreement alone.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-049","question":"The Los Angeles wildfires of January 2025 caused approximately how much damage?","options":["$10 billion","$30 billion","$65 billion","$100 billion"],"answer":2,"explanation":"The January 2025 Los Angeles wildfires caused approximately $65 billion in damage.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-050","question":"The 33rd SEA Games in 2025 was hosted by:","options":["Vietnam","Indonesia","Thailand","Philippines"],"answer":2,"explanation":"Thailand hosted the 33rd SEA Games (9-20 December 2025) in Bangkok, Chonburi, and Songkhla.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-051","question":"The Paris Agreement aims to limit global temperature rise to:","options":["1 degrees C above pre-industrial levels","1.5 degrees C (or below 2 degrees C) above pre-industrial levels","2.5 degrees C above 1990 levels","3 degrees C above current levels"],"answer":1,"explanation":"The Paris Agreement (2015) aims to limit global temperature rise to 1.5 degrees C, or at least below 2 degrees C, above pre-industrial levels.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-052","question":"Which gas is primarily responsible for ozone depletion?","options":["CO2","CH4","N2O","CFCs"],"answer":3,"explanation":"CFCs (chlorofluorocarbons) from old refrigerators, aerosol sprays, and air conditioners cause ozone depletion. The Montreal Protocol (1987) addresses this.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-053","question":"The Montreal Protocol (1987) addresses:","options":["Climate change and CO2 emissions","Ozone depletion from CFCs","Acid rain from SO2","Nuclear weapons testing"],"answer":1,"explanation":"The Montreal Protocol (1987) is the most widely ratified environmental treaty (197 parties), addressing ozone depletion caused by CFCs.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-054","question":"The Ring of Fire accounts for approximately what percentage of the world's earthquakes?","options":["50%","70%","80%","90%"],"answer":3,"explanation":"The Ring of Fire accounts for about 90% of the world's earthquakes and about 75% of its active volcanoes.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-055","question":"Which two ASEAN countries are at highest risk from the Ring of Fire?","options":["Thailand and Malaysia","Vietnam and Cambodia","Philippines and Indonesia","Myanmar and Laos"],"answer":2,"explanation":"The Philippines and Indonesia are the two highest-risk ASEAN countries, as they lie directly along the Ring of Fire.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-056","question":"El Nino typically causes what effect in Southeast Asia?","options":["Heavy rainfall and flooding","Drought","Cooler temperatures","Stronger typhoons"],"answer":1,"explanation":"El Nino (abnormally warm Pacific water) causes drought in Southeast Asia and heavy rain in South America.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-057","question":"Which COP first produced an agreement to 'transition away from fossil fuels'?","options":["COP26 (Glasgow)","COP27 (Sharm el-Sheikh)","COP28 (Dubai)","COP29 (Baku)"],"answer":2,"explanation":"COP28 in Dubai (2023) was historic as the first COP to produce an agreement to 'transition away from fossil fuels.'","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-058","question":"The COP27 meeting established:","options":["The Paris Agreement","The Loss and Damage Fund","The NCQG on climate finance","The Bletchley Declaration"],"answer":1,"explanation":"COP27 in Sharm el-Sheikh, Egypt (2022) established the Loss and Damage Fund to help vulnerable countries affected by climate disasters.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-059","question":"Which gas is the main greenhouse gas causing climate change?","options":["CFCs","N2O","CO2","SO2"],"answer":2,"explanation":"CO2 (carbon dioxide) is the primary greenhouse gas driving climate change, produced mainly by burning fossil fuels.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-060","question":"The Bletchley Declaration (2023) related to:","options":["Climate change","AI safety governance","Nuclear disarmament","Trade liberalization"],"answer":1,"explanation":"The AI Safety Summit at Bletchley Park (2023) produced the Bletchley Declaration, signed by 28 countries — the first multilateral AI-governance framework.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-061","question":"Russia launched its full-scale invasion of Ukraine on:","options":["24 February 2021","24 February 2022","14 March 2022","7 April 2022"],"answer":1,"explanation":"Russia launched its full-scale invasion of Ukraine on 24 February 2022.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-062","question":"What technology kept Ukraine's military communications operational during the war?","options":["SpaceX Starship","Starlink satellite internet","Amazon Alexa","Google Cloud"],"answer":1,"explanation":"Starlink (SpaceX / Elon Musk) — a network of 5,000+ satellites — kept Ukraine's military communications operational.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-063","question":"The Palestinian death toll in the Gaza War exceeded how many by early 2026?","options":["20,000","35,000","50,000","75,000"],"answer":2,"explanation":"By early 2026, the Palestinian death toll in the Gaza War exceeded 50,000.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-064","question":"Which court ordered Israel to prevent acts of genocide (Jan 2024)?","options":["ICC","ICJ","UNSC","European Court of Human Rights"],"answer":1,"explanation":"The ICJ (International Court of Justice) ordered Israel to prevent acts of genocide after South Africa filed a case in January 2024.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-065","question":"The ICC issued arrest warrants for which leader in November 2024?","options":["Volodymyr Zelenskyy","Vladimir Putin","Benjamin Netanyahu","Yahya Sinwar"],"answer":2,"explanation":"The ICC issued arrest warrants for Netanyahu (and former Israeli defence minister) and Hamas leaders in November 2024.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-066","question":"The Phase 1 Gaza ceasefire took effect on:","options":["7 October 2024","19 January 2025","1 March 2025","10 October 2025"],"answer":1,"explanation":"Phase 1 of the Gaza ceasefire took effect on 19 January 2025, brokered by Qatar.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-067","question":"Yahya Sinwar, Hamas leader, was killed in:","options":["September 2024","October 2024","January 2025","March 2025"],"answer":1,"explanation":"Yahya Sinwar, Hamas leader, was killed in October 2024 — a pivotal moment in the Gaza War.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-068","question":"Russia annexed Crimea in:","options":["2012","2013","2014","2015"],"answer":2,"explanation":"Russia annexed Crimea in 2014, after Ukraine's Maidan revolution.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-069","question":"In February 2026, Xi Jinping called Trump and Putin to signal:","options":["China's military support for Russia","China's willingness to mediate the Ukraine conflict","China's withdrawal from the UN","China's support for Gaza"],"answer":1,"explanation":"On the same day in February 2026, Xi called both Trump and Putin, signalling China's readiness to mediate the Ukraine conflict.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-070","question":"ChatGPT was launched by which company?","options":["Google","Meta","OpenAI","Microsoft"],"answer":2,"explanation":"ChatGPT was launched by OpenAI in November 2022, reaching 100 million users in just 2 months.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-071","question":"The EU AI Act is the world's first:","options":["AI research framework","Comprehensive AI law","AI safety test","National AI strategy"],"answer":1,"explanation":"The EU AI Act (passed June 2024) is the world's first comprehensive AI law, with four risk tiers.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-072","question":"The EU AI Act became fully enforced in:","options":["January 2025","June 2025","January 2026","June 2026"],"answer":1,"explanation":"The EU AI Act was fully enforced from June 2025, with GPAI rules applying to ChatGPT, GPT-4, Gemini, and similar systems.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-073","question":"DeepSeek is an AI model from:","options":["USA","China","South Korea","Japan"],"answer":1,"explanation":"DeepSeek is a Chinese AI model that launched in 2025 competitive with top U.S. AI at lower cost, shocking NVIDIA's share price.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-074","question":"Starlink is a:","options":["Social media platform","Rocket program","Satellite internet network","Cloud computing service"],"answer":2,"explanation":"Starlink is SpaceX's network of 5,000+ internet satellites, used in the Ukraine war and in remote areas worldwide.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-075","question":"Elon Musk's role in the Trump administration (2025-2026) is:","options":["Secretary of State","Head of DOGE (Dept. of Government Efficiency)","Director of NASA","National Security Advisor"],"answer":1,"explanation":"Musk heads DOGE (Department of Government Efficiency) as Trump's adviser.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-076","question":"GPT-4 achieved which milestone in March 2023?","options":["Reached 1 billion users","Passed bar exams and medical licensing tests at human level","Was banned in Europe","Achieved quantum computing integration"],"answer":1,"explanation":"GPT-4 (March 2023) passed bar exams and medical licensing tests at human level.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-077","question":"The BLM movement gained global momentum following:","options":["The death of Trayvon Martin in 2020","The killing of George Floyd in 2020","A Supreme Court ruling in 2019","Police violence in Baltimore in 2015"],"answer":1,"explanation":"While BLM originated in 2013, it gained massive global momentum in 2020 following the killing of George Floyd by police.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-078","question":"The #MeToo movement became global in:","options":["2006","2013","2017","2020"],"answer":2,"explanation":"#MeToo was created in 2006 (Tarana Burke) but became a global movement in 2017 following the Harvey Weinstein expose.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-079","question":"Human trafficking is legally defined as recruitment or transport of persons for exploitation through:","options":["Voluntary migration","Force, fraud, or coercion","Legal work permits","Tourism agreements"],"answer":1,"explanation":"Human trafficking involves recruitment, transport, or harbouring by force, fraud, or coercion for exploitation.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-080","question":"The Palermo Protocol (2000) addresses:","options":["Nuclear proliferation","Human trafficking","Climate change","Drug trafficking"],"answer":1,"explanation":"The Palermo Protocol (2000) is the UN Protocol to Prevent, Suppress and Punish Trafficking in Persons.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-081","question":"Trump in 2025 raised tariffs on Chinese goods to as high as:","options":["25%","50%","100%","145%"],"answer":3,"explanation":"In Trump's second term (2025), tariffs on some Chinese goods were raised to 145%; China retaliated with 125% tariffs.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-082","question":"The concept of 'sustainable development' was defined in the Brundtland Report of:","options":["1972","1980","1987","1992"],"answer":2,"explanation":"The Brundtland Report (1987) defined sustainable development as 'meeting the needs of the present without compromising future generations.'","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-083","question":"UDHR Article 19 protects:","options":["Right to life","No torture","Freedom of expression","Right to asylum"],"answer":2,"explanation":"UDHR Article 19 protects freedom of opinion and expression.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-084","question":"The 2028 Olympics will be held in:","options":["Brisbane","Paris","Los Angeles","Tokyo"],"answer":2,"explanation":"The 2028 Olympics will be held in Los Angeles, USA, adding 22 events vs Paris including Cricket, Flag Football, and Lacrosse.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-085","question":"The 2032 Olympics will be held in:","options":["Brisbane, Australia","Sydney, Australia","Mumbai, India","Doha, Qatar"],"answer":0,"explanation":"Brisbane, Australia will host the 2032 Summer Olympics.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-086","question":"The 2034 FIFA World Cup will be hosted by:","options":["Spain and Portugal","Australia","Saudi Arabia","Morocco"],"answer":2,"explanation":"Saudi Arabia will host the 2034 FIFA World Cup.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-087","question":"The 2023 Nobel Peace Prize was awarded to:","options":["Nihon Hidankyo","Maria Corina Machado","Narges Mohammadi","Ales Bialiatski"],"answer":2,"explanation":"Narges Mohammadi of Iran won the 2023 Nobel Peace Prize for her fight for women's rights in Iran.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-088","question":"The 2026 Asian Games will be held in:","options":["Hangzhou, China","Jakarta, Indonesia","Aichi-Nagoya, Japan","Seoul, South Korea"],"answer":2,"explanation":"The 2026 Asian Games will be held in Aichi-Nagoya, Japan in September-October 2026.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-089","question":"Where were the 2023 Asian Games held?","options":["Bangkok, Thailand","Hangzhou, China","Kuala Lumpur, Malaysia","Manila, Philippines"],"answer":1,"explanation":"The 2022 Asian Games were postponed to 2023 and held in Hangzhou, China.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-090","question":"Which new sport was added to the 2028 Los Angeles Olympics?","options":["Squash","Cricket","Polo","Volleyball Beach"],"answer":1,"explanation":"Cricket (along with Flag Football and Lacrosse) will be added to the 2028 Los Angeles Olympics.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-091","question":"The current ASEAN Secretary-General is:","options":["Lim Jock Hoi","Surin Pitsuwan","Kao Kim Hourn","Le Luong Minh"],"answer":2,"explanation":"Dr. Kao Kim Hourn of Cambodia has been ASEAN Secretary-General since 1 January 2023, serving until 31 December 2027.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-092","question":"The ASEAN Secretary-General's term is:","options":["3 years, renewable","4 years, non-renewable","5 years, non-renewable","10 years, renewable"],"answer":2,"explanation":"The ASEAN Secretary-General serves a non-renewable 5-year term, per the ASEAN Charter.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-093","question":"The ASEAN Chairmanship rotates in what order?","options":["By population size","By GDP","Alphabetical order of member-state names in English","By date of joining ASEAN"],"answer":2,"explanation":"Per ASEAN Charter Article 31, the Chairmanship rotates annually in alphabetical order of member-state names in English.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-094","question":"Which country is the ASEAN Chair in 2026?","options":["Malaysia","Myanmar","Philippines","Singapore"],"answer":2,"explanation":"The Philippines is ASEAN Chair in 2026, with the theme 'Navigating Our Future, Together.' Myanmar was skipped due to its 2021 coup.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-095","question":"Why was Myanmar skipped in the ASEAN Chairmanship rotation for 2026?","options":["Myanmar withdrew from ASEAN","Myanmar was expelled from ASEAN","Its military coup made it unable to host","Myanmar declined the Chairmanship"],"answer":2,"explanation":"Myanmar's military coup in 2021 made it unable to fulfill Chairmanship duties, so ASEAN members agreed to skip Myanmar in 2026.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-096","question":"The 2025 ASEAN Summit theme under Malaysia was:","options":["Epicentrum of Growth","Enhancing Connectivity and Resilience","Inclusivity and Sustainability","Navigating Our Future, Together"],"answer":2,"explanation":"Malaysia's 2025 ASEAN Chairmanship theme was 'Inclusivity and Sustainability.' It was the year Timor-Leste joined as the 11th member.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-097","question":"The 2024 ASEAN Summit was hosted by:","options":["Indonesia","Laos","Malaysia","Philippines"],"answer":1,"explanation":"Laos hosted the 2024 ASEAN Summits (44th-45th) in Vientiane under the theme 'Enhancing Connectivity and Resilience.'","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-098","question":"Timor-Leste joined ASEAN at which Summit number?","options":["44th","45th","46th","47th"],"answer":3,"explanation":"Timor-Leste joined ASEAN at the 47th Summit on 26 October 2025 in Kuala Lumpur — the first expansion since Cambodia joined in 1999.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-099","question":"When is Timor-Leste scheduled to chair ASEAN?","options":["2027","2028","2029","2030"],"answer":2,"explanation":"Timor-Leste is confirmed to chair ASEAN in 2029, as agreed following its membership.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-100","question":"Indonesia's current President is:","options":["Joko Widodo","Prabowo Subianto","Megawati Sukarnoputri","Anwar Ibrahim"],"answer":1,"explanation":"Prabowo Subianto won Indonesia's February 2024 election with 59% and was inaugurated on 20 October 2024.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-101","question":"Cambodia's current Prime Minister is:","options":["Hun Sen","Hun Manet","Sam Rainsy","Kem Sokha"],"answer":1,"explanation":"Hun Manet became Cambodia's PM in August 2023 when his father Hun Sen stepped down after 38+ years — a dynastic transfer.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-102","question":"Singapore's current Prime Minister is:","options":["Lee Hsien Loong","Goh Chok Tong","Lawrence Wong","Tharman Shanmugaratnam"],"answer":2,"explanation":"Lawrence Wong became Singapore's PM in May 2024, succeeding Lee Hsien Loong.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-103","question":"Thailand's current Prime Minister (as of March 2026) is:","options":["Prayuth Chan-o-cha","Srettha Thavisin","Paetongtarn Shinawatra","Anutin Charnvirakul"],"answer":3,"explanation":"Anutin Charnvirakul became Thailand's PM in September 2025, after the Constitutional Court removed Paetongtarn Shinawatra on ethical grounds.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-104","question":"Which ASEAN country is the only one with an absolute monarchy?","options":["Thailand","Malaysia","Cambodia","Brunei"],"answer":3,"explanation":"Brunei is ASEAN's only absolute monarchy, where Sultan Hassanal Bolkiah holds supreme political and religious authority.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-105","question":"The ONLY landlocked ASEAN country is:","options":["Cambodia","Myanmar","Laos","Vietnam"],"answer":2,"explanation":"Laos is the only landlocked ASEAN country, which is why Connectivity was central to its 2024 Chairmanship theme.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-106","question":"Which ASEAN country uses the US dollar as its currency?","options":["Cambodia","Philippines","Timor-Leste","Myanmar"],"answer":2,"explanation":"Timor-Leste uses the US dollar as its official currency.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-107","question":"The majority religion in the Philippines is:","options":["Islam","Buddhism","Hinduism","Christianity (Catholic)"],"answer":3,"explanation":"The Philippines is the only ASEAN country with a majority Catholic Christian population.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-108","question":"Indonesia has the world's largest population of which religion?","options":["Buddhism","Hinduism","Islam","Christianity"],"answer":2,"explanation":"Indonesia has the world's largest Muslim population, making Islam its majority religion.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-109","question":"Which ASEAN countries share a border with China?","options":["Thailand, Vietnam, Cambodia","Myanmar, Laos, Vietnam","Malaysia, Indonesia, Philippines","Brunei, Singapore, Malaysia"],"answer":1,"explanation":"Myanmar, Laos, and Vietnam all border China — making them strategically significant.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-110","question":"Countries near or on the Equator in ASEAN include:","options":["Thailand, Vietnam, Cambodia","Philippines, Myanmar, Laos","Indonesia, Malaysia, Singapore, Brunei","All ASEAN countries"],"answer":2,"explanation":"Indonesia, Malaysia, Singapore, and Brunei are located near or on the Equator.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-111","question":"Myanmar's government type is currently best described as:","options":["Parliamentary democracy","Presidential republic","Military dictatorship","Constitutional monarchy"],"answer":2,"explanation":"Myanmar has been a military dictatorship since the February 2021 coup by Min Aung Hlaing.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-112","question":"Which ASEAN country passed power dynastically in 2023?","options":["Vietnam","Cambodia","Thailand","Singapore"],"answer":1,"explanation":"Cambodia passed power dynastically when Hun Sen handed the PM position to his son Hun Manet in August 2023.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-113","question":"The South China Sea dispute falls under which ASEAN pillar?","options":["AEC","ASCC","APSC","All three pillars"],"answer":2,"explanation":"The South China Sea dispute is a political-security issue falling under the APSC (ASEAN Political-Security Community) pillar.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-114","question":"Transboundary haze falls primarily under which ASEAN pillar?","options":["APSC","AEC","ASCC","None"],"answer":2,"explanation":"Transboundary haze is an environmental and societal issue primarily under ASCC (ASEAN Socio-Cultural Community).","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-115","question":"The ASEAN Digital Economy Framework Agreement (DEFA) falls under which pillar?","options":["APSC","AEC","ASCC","APSC and AEC"],"answer":1,"explanation":"DEFA is an economic cooperation initiative falling under the AEC (ASEAN Economic Community) pillar.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-116","question":"The AEC aims to create:","options":["A common currency like the euro","A single market and production base","A joint military alliance","A single government for ASEAN"],"answer":1,"explanation":"The AEC aims to create a single market and production base, not a political union or single currency.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-117","question":"Does the AEC include a single ASEAN currency?","options":["Yes, similar to the euro","No, only currency cooperation to reduce USD reliance","Yes, from 2025","Only for Singapore and Malaysia"],"answer":1,"explanation":"The AEC does NOT include a single currency. Member economies vary enormously in size and development.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-118","question":"How many professions are covered by ASEAN Mutual Recognition Arrangements (MRAs)?","options":["5","6","8","10"],"answer":2,"explanation":"ASEAN MRAs cover 8 professions: Engineers, Architects, Nurses, Surveyors, Accountants, Dental Practitioners, Medical Practitioners, and Tourism Professionals.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-119","question":"Which profession is NOT covered by ASEAN MRAs?","options":["Engineers","Architects","Lawyers","Nurses"],"answer":2,"explanation":"Lawyers are NOT covered by ASEAN MRAs. Only 8 specific professions have MRAs.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-120","question":"The Rohingya refugee crisis falls primarily under:","options":["AEC","APSC and ASCC","AEC and APSC","AEC alone"],"answer":1,"explanation":"The Rohingya crisis has both a human rights dimension (APSC) and humanitarian welfare dimension (ASCC).","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-121","question":"How many countries are members of RCEP?","options":["10","12","15","18"],"answer":2,"explanation":"RCEP has 15 members: all 10 ASEAN states plus China, Japan, South Korea, Australia, and New Zealand.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-122","question":"RCEP was signed on:","options":["1 January 2020","15 November 2020","1 January 2022","15 November 2022"],"answer":1,"explanation":"RCEP was signed on 15 November 2020 (online due to COVID-19). It entered into force on 1 January 2022.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-123","question":"Which country withdrew from RCEP negotiations in 2019?","options":["Australia","India","Japan","South Korea"],"answer":1,"explanation":"India withdrew from RCEP negotiations in 2019. The USA was never a member.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-124","question":"RCEP covers approximately what share of global population and GDP?","options":["15%","20%","30%","45%"],"answer":2,"explanation":"RCEP covers roughly 30% of global population and GDP, making it the world's largest free trade agreement.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-125","question":"Which ASEAN countries are members of CPTPP?","options":["Thailand, Philippines, Indonesia, Malaysia","Brunei, Malaysia, Singapore, Vietnam","All 10 ASEAN members","Singapore, Malaysia, Thailand, Vietnam"],"answer":1,"explanation":"The ASEAN CPTPP members are Brunei, Malaysia, Singapore, and Vietnam.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-126","question":"The UK joined CPTPP in:","options":["January 2023","June 2024","December 2024","March 2025"],"answer":2,"explanation":"The United Kingdom joined CPTPP in December 2024.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-127","question":"The Laos-China railway (Vientiane-Kunming) is an example of:","options":["AFTA","BRI (Belt and Road Initiative)","RCEP","CPTPP"],"answer":1,"explanation":"The Vientiane-Kunming Railway is a key BRI project that transformed Laos from 'landlocked' to 'land-linked.'","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-128","question":"AFTA (ASEAN Free Trade Area) was established in:","options":["1967","1985","1992","2003"],"answer":2,"explanation":"AFTA was established in 1992 as ASEAN's first free trade area, using the CEPT mechanism to reduce intra-ASEAN tariffs to 0-5%.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-129","question":"GMS (Greater Mekong Subregion) has how many members?","options":["4","5","6","7"],"answer":2,"explanation":"GMS has 6 members: Cambodia, China (Yunnan & Guangxi), Laos, Myanmar, Thailand, and Vietnam — founded in 1992 by ADB.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-130","question":"China is a member of GMS but NOT a member of:","options":["BRI","RCEP","ASEAN","CPTPP"],"answer":2,"explanation":"China is a GMS member but is NOT an ASEAN member — a common exam trap!","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-131","question":"CLMV stands for:","options":["China, Laos, Malaysia, Vietnam","Cambodia, Laos, Myanmar, Vietnam","Cambodia, Laos, Myanmar, Malaysia","China, Laos, Myanmar, Vietnam"],"answer":1,"explanation":"CLMV = Cambodia, Laos, Myanmar, Vietnam — the four ASEAN latecomers who joined 1995-1999.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-132","question":"Thailand's EEC (Eastern Economic Corridor) covers how many provinces?","options":["Two","Three","Four","Five"],"answer":1,"explanation":"EEC covers three provinces: Chachoengsao, Chonburi, and Rayong (~13,266 sq km).","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-133","question":"The EEC supports which Thai national policy?","options":["Thailand 3.0","Thailand 4.0","ASEAN Vision 2025","BRI Phase 2"],"answer":1,"explanation":"EEC is the core of Thailand 4.0, aiming to shift from low-cost manufacturing to technology and innovation.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-134","question":"The 5th RCEP Summit was held in:","options":["October 2024","October 2025","January 2026","June 2025"],"answer":1,"explanation":"The 5th RCEP Summit was held in October 2025 with Malaysia hosting — the first time leaders met together since RCEP was signed.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-135","question":"Which principle of the ASEAN Way means decisions require all members to agree?","options":["Non-interference","Non-use of Force","Consultation and Consensus","Quiet Diplomacy"],"answer":2,"explanation":"Consultation and Consensus means all ASEAN decisions require agreement from all members — no majority vote can override.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-136","question":"The Myanmar crisis tests which ASEAN Way principle most directly?","options":["Non-use of Force","Non-interference","Consensus","Quiet Diplomacy"],"answer":1,"explanation":"Non-interference prevents ASEAN from acting on Myanmar's domestic situation despite 90,000 deaths and 5.2 million displaced.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-137","question":"The Thailand-Cambodia border peace deal (Oct. 2025) is an example of:","options":["ASEAN failing to act","Non-interference in action","Quiet diplomacy working effectively","ASEAN use of military force"],"answer":2,"explanation":"Malaysia mediated quietly between Thailand and Cambodia after July 2025 border clashes, resulting in a peace agreement.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-138","question":"Which of the following is a Non-Traditional Security (NTS) threat?","options":["Military invasion","Nuclear deterrence","Transboundary haze","Territorial disputes"],"answer":2,"explanation":"Transboundary haze is a NTS threat — non-military, cross-border, endangering people's wellbeing.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-139","question":"The 'Golden Triangle' in ASEAN is associated with:","options":["Tourism","Drug trafficking","Gold mining","Trade in electronics"],"answer":1,"explanation":"The Golden Triangle (border area of Thailand, Laos, and Myanmar) is infamous for drug trafficking — a major NTS threat.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-140","question":"ASEAN Centrality means:","options":["ASEAN's economy is the center of global trade","ASEAN is geographically central in Asia","ASEAN is the hub of regional architecture and cooperation","ASEAN has equal power to the USA and China"],"answer":2,"explanation":"ASEAN Centrality means ASEAN serves as the hub and driving force of regional architecture.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-141","question":"The Five-Point Consensus on Myanmar (2021) is:","options":["A legally binding UN resolution","A voluntary framework with no enforcement mechanism","An ASEAN military intervention plan","An economic sanctions regime"],"answer":1,"explanation":"The Five-Point Consensus is a voluntary, non-binding framework — ASEAN has no mechanism to enforce it.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-142","question":"Myanmar's military coup was led by:","options":["Aung San Suu Kyi","Min Aung Hlaing","Thein Sein","Win Myint"],"answer":1,"explanation":"General Min Aung Hlaing led the February 2021 coup that overthrew Aung San Suu Kyi's elected NLD government.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-143","question":"The Rohingya are a Muslim minority in which Myanmar state?","options":["Shan State","Kachin State","Rakhine State","Karen State"],"answer":2,"explanation":"The Rohingya are a Muslim minority in Rakhine State who have been denied Myanmar citizenship.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-144","question":"Where are most Rohingya refugees sheltered?","options":["Thailand","India","Bangladesh","Malaysia"],"answer":2,"explanation":"Most Rohingya refugees are in Bangladesh — Cox's Bazar is the world's largest refugee camp hosting over 1 million people.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-145","question":"Cox's Bazar is the world's largest:","options":["Fishing port","Refugee camp","Beach resort","Industrial zone"],"answer":1,"explanation":"Cox's Bazar in Bangladesh is the world's largest refugee camp, hosting over 1 million Rohingya refugees.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-146","question":"China's claim in the South China Sea is known as the:","options":["Seven-Dash Line","Nine-Dash Line","Ten-Dash Line","Twelve-Dash Line"],"answer":1,"explanation":"China claims about 90% of the South China Sea through its Nine-Dash Line, which extends far into neighboring nations' EEZs.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-147","question":"The 2016 PCA ruling on the South China Sea found:","options":["China's claims are valid under UNCLOS","China's Nine-Dash Line is incompatible with UNCLOS","The Philippines has no rights in the Spratlys","All claimants have equal rights"],"answer":1,"explanation":"The Permanent Court of Arbitration ruled China's Nine-Dash Line incompatible with UNCLOS. China rejects this ruling.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-148","question":"Which country brought the 2016 South China Sea PCA case?","options":["Vietnam","Malaysia","Brunei","Philippines"],"answer":3,"explanation":"The Philippines filed the arbitration case against China that led to the 2016 PCA ruling.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-149","question":"Which ASEAN country is NOT a South China Sea claimant?","options":["Vietnam","Philippines","Thailand","Malaysia"],"answer":2,"explanation":"Thailand, Laos, Cambodia, and Myanmar are NOT involved in South China Sea territorial claims.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-150","question":"The primary source of ASEAN transboundary haze is:","options":["Malaysia","Singapore","Indonesia","Brunei"],"answer":2,"explanation":"Indonesia (Sumatra and Kalimantan/Borneo) is the primary source, from burning forests for palm oil and pulp plantations.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-151","question":"The ASEAN Agreement on Transboundary Haze Pollution was signed in:","options":["1997","2002","2010","2015"],"answer":1,"explanation":"The ASEAN Agreement on Transboundary Haze Pollution was signed in 2002. The target is a haze-free ASEAN by 2030.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-152","question":"The ACC THPC (haze-control centre) was launched at which ASEAN Summit?","options":["2021 Summit","2022 Summit","2023 Jakarta Summit","2024 Summit"],"answer":2,"explanation":"The ACC THPC (ASEAN Coordinating Centre for Transboundary Haze Pollution Control) was launched at the 2023 Jakarta Summit.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-153","question":"In 2025, Thailand-Cambodia border clashes near Preah Vihear resulted in:","options":["Full-scale war","12 killed and 500,000+ displaced","A UN peacekeeping deployment","Myanmar military involvement"],"answer":1,"explanation":"The July 2025 Thai-Cambodian border clashes near Preah Vihear resulted in 12 killed and over 500,000 displaced.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-154","question":"The ASEAN Charter Article 31 deals with:","options":["Human rights","Chairmanship rotation","ASEAN's legal personality","Environmental protection"],"answer":1,"explanation":"ASEAN Charter Article 31 governs the annual Chairmanship rotation in alphabetical order of member-state names in English.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-155","question":"ASEAN was founded in:","options":["1945","1955","1967","1975"],"answer":2,"explanation":"ASEAN was founded on 8 August 1967 in Bangkok by its five founding members: Indonesia, Malaysia, Philippines, Singapore, and Thailand.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-156","question":"The original ASEAN had how many founding members?","options":["4","5","6","7"],"answer":1,"explanation":"ASEAN had 5 founding members: Indonesia, Malaysia, Philippines, Singapore, and Thailand.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-157","question":"Which country is the largest ASEAN economy by GDP?","options":["Thailand","Malaysia","Indonesia","Philippines"],"answer":2,"explanation":"Indonesia is ASEAN's largest economy and is the region's only G20 member by right of its own size.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-158","question":"The ASEAN Charter was adopted in:","options":["1995","2001","2007","2012"],"answer":2,"explanation":"The ASEAN Charter was adopted in 2007, giving ASEAN a formal legal personality and institutional framework.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-159","question":"Which is NOT a goal of the AEC?","options":["Free flow of goods","Free flow of services","Single currency like the euro","Free flow of investment"],"answer":2,"explanation":"A single currency is NOT a goal of the AEC. The AEC aims for free flow of goods, services, investment, and skilled labour.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-160","question":"ASEAN's motto is:","options":["Unity in Diversity","One Vision, One Identity, One Community","Peace, Progress, Prosperity","Together We Thrive"],"answer":1,"explanation":"ASEAN's motto is 'One Vision, One Identity, One Community.'","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-161","question":"Which non-ASEAN country is a member of GMS?","options":["India","China","Japan","South Korea"],"answer":1,"explanation":"China (specifically Yunnan and Guangxi provinces) is a GMS member but NOT an ASEAN member.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-162","question":"The IAI (Initiative for ASEAN Integration) provides support to:","options":["All ASEAN members equally","CLMV countries to close the development gap","Only Singapore and Malaysia","Non-ASEAN partners"],"answer":1,"explanation":"The IAI targets CLMV countries (Cambodia, Laos, Myanmar, Vietnam) to help close the development gap.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-163","question":"Thailand changed Prime Ministers how many times between 2023 and 2026?","options":["Once","Twice","Three times","Four times"],"answer":2,"explanation":"Thailand had three PMs: Srettha Thavisin, Paetongtarn Shinawatra (removed by Constitutional Court), and Anutin Charnvirakul (Sept. 2025).","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-164","question":"Paetongtarn Shinawatra was removed as Thailand's PM on what grounds?","options":["Corruption","Vote-rigging","Ethical grounds","Treason"],"answer":2,"explanation":"Thailand's Constitutional Court removed Paetongtarn Shinawatra on ethical grounds on 29 August 2025.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-165","question":"Which South China Sea feature saw China use water cannons against Philippine ships in 2025?","options":["Scarborough Shoal","Second Thomas Shoal","Paracel Islands","Spratly Islands main group"],"answer":1,"explanation":"In 2025, China repeatedly used water cannons and maritime militia vessels against Philippine ships at Second Thomas Shoal.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-166","question":"The 'Strait of Hormuz Crisis' in March 2026 was caused by:","options":["OPEC cutting oil production","Iran retaliating against US-Israel strikes","Saudi Arabia blocking the strait","A major oil spill"],"answer":1,"explanation":"After the February 2026 US-Israeli strikes on Iran, Iran retaliated by striking oil infrastructure and ships in the Strait of Hormuz, dropping commercial traffic by 90%.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-167","question":"Operation Epic Fury (February 2026) was a military campaign by:","options":["NATO against Russia","USA and Israel against Iran","USA against Venezuela","Israel against Hamas"],"answer":1,"explanation":"On 28 February 2026, the USA and Israel launched Operation Epic Fury — nearly 900 strikes on Iran in 12 hours.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-168","question":"Min Aung Hlaing's political transition in April 2026 involved:","options":["Genuine democratic election","Stepping down in favour of Aung San Suu Kyi","Being elected president by the Electoral College with 429 votes","Exile to China"],"answer":2,"explanation":"On 3 April 2026, Min Aung Hlaing was elected president by the Electoral College with 429 votes — analysts see this as consolidation of power.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-169","question":"The NASA Artemis II mission (April 2026) was significant because:","options":["It was the first crewed Mars flyby","It was the first crewed lunar flyby in 50 years","It established a permanent moon base","It was the first all-female crew in space"],"answer":1,"explanation":"The Artemis II mission (April 2026) was the first crewed lunar flyby in 50 years.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-170","question":"Moldova's parliament voted to withdraw from which organisation in April 2026?","options":["NATO","European Union","CIS (Commonwealth of Independent States)","OSCE"],"answer":2,"explanation":"On 2 April 2026, Moldova's parliament voted to withdraw from the CIS, citing Russia's violations of sovereignty principles.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-171","question":"The US-Iran ceasefire in April 2026 was brokered by:","options":["China alone","Russia and Turkey","Pakistan with last-minute help from China","Qatar and Egypt"],"answer":2,"explanation":"President Trump announced a two-week US-Iran ceasefire on 7-8 April 2026, brokered by Pakistan with a last-minute push from China.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-172","question":"Hantavirus is primarily transmitted to humans via:","options":["Mosquito bites","Inhalation of aerosolized rodent droppings, urine, or saliva","Contaminated water","Person-to-person droplets"],"answer":1,"explanation":"Hantaviruses are transmitted primarily through inhalation of aerosolized droppings, urine, or saliva from infected rodent reservoirs.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-173","question":"HCPS (Hantavirus Cardiopulmonary Syndrome) has a fatality rate of up to:","options":["10%","25%","50%","75%"],"answer":2,"explanation":"HCPS in the Americas targets the lungs and heart with a fatality rate of up to 50%. There are no specific antiviral treatments or vaccines.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-174","question":"Which Hantavirus strain is notable for limited person-to-person transmission?","options":["Sin Nombre virus","Seoul virus","Andes virus","Hantaan virus"],"answer":2,"explanation":"The Andes virus in South America is a notable exception where limited person-to-person spread can occur through close contact.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-175","question":"Why should you AVOID dry sweeping when cleaning areas contaminated with rodent droppings?","options":["It damages the floor","It prevents the virus from becoming airborne","Dry sweeping disturbs the rodents","It wastes cleaning materials"],"answer":1,"explanation":"Dry sweeping causes the Hantavirus to become airborne. Dampening contaminated areas before cleaning is a critical safety protocol.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-176","question":"The Milan-Cortina 2026 Winter Olympics was held in:","options":["6-22 February 2026","February-March 2026","March-April 2026","December 2025"],"answer":0,"explanation":"The Milan-Cortina Winter Olympics ran from 6 to 22 February 2026.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-177","question":"New START treaty expiration in February 2026 removed the last pillar of:","options":["Nuclear energy cooperation","Cold War-era arms control","Anti-terrorism agreements","Chemical weapons treaties"],"answer":1,"explanation":"The New START treaty limiting US and Russian strategic nuclear weapons expired in February 2026, removing a key remaining pillar of Cold War-era arms control.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-178","question":"Which ASEAN country changed PM three times in two years (2023-2025)?","options":["Indonesia","Malaysia","Philippines","Thailand"],"answer":3,"explanation":"Thailand had three PMs in two years: Srettha Thavisin, then Paetongtarn Shinawatra (removed), then Anutin Charnvirakul.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-179","question":"ASEAN's founding members met in which city?","options":["Jakarta","Kuala Lumpur","Bangkok","Manila"],"answer":2,"explanation":"ASEAN was founded on 8 August 1967 in Bangkok, Thailand, with the signing of the Bangkok Declaration.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-180","question":"The 2023 ASEAN Summit theme under Indonesia was:","options":["Enhancing Connectivity and Resilience","Epicentrum of Growth","Inclusivity and Sustainability","Navigating Our Future, Together"],"answer":1,"explanation":"Indonesia's 2023 ASEAN Chairmanship theme was 'ASEAN Matters: Epicentrum of Growth.'","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-181","question":"Which ASEAN document was signed in 2025 to advance digital economy cooperation?","options":["RCEP upgrade agreement","AFTA 2.0","DEFA (Digital Economy Framework Agreement)","ASEAN Cyber Treaty"],"answer":2,"explanation":"The ASEAN Digital Economy Framework Agreement (DEFA) was signed in 2025 under Malaysia's chairmanship, effective 2026.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-182","question":"The Great Mekong Subregion's three goals are:","options":["Peace, Progress, Prosperity","Community, Connectivity, Competitiveness","Trade, Tourism, Technology","Development, Diplomacy, Democracy"],"answer":1,"explanation":"The GMS three goals are Community, Connectivity, and Competitiveness.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-183","question":"Under ASEAN's MRA system, which category of worker can practice across member states?","options":["All workers with a university degree","General labor with work permits","8 specific skilled professions","All ASEAN citizens automatically"],"answer":2,"explanation":"MRAs cover only 8 specific skilled professions. General labor and many other professionals are NOT covered.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-184","question":"The CEPT mechanism under AFTA aims to reduce intra-ASEAN tariffs to:","options":["10-15%","5-10%","0-5%","Zero"],"answer":2,"explanation":"The CEPT (Common Effective Preferential Tariff) under AFTA reduces intra-ASEAN import tariffs to 0-5%.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-185","question":"Trump proposed readmitting Russia to the G7/G8 at the 2025 G7 Summit. The allies:","options":["Accepted the proposal","Rejected it","Postponed the decision","Agreed to a smaller G7"],"answer":1,"explanation":"Trump proposed readmitting Russia to a reconstituted G8, but the proposal was rejected by G7 allies.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-186","question":"Narges Mohammadi received the 2023 Nobel Peace Prize while:","options":["Giving a speech in Oslo","In exile in Germany","Imprisoned in Iran (could not attend)","Serving as Iran's Minister of Culture"],"answer":2,"explanation":"Narges Mohammadi was imprisoned in Iran and could not attend the Nobel Peace Prize ceremony in Oslo.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-187","question":"The SDG Report 2025 found that electricity access now covers what percentage of the world?","options":["84%","88.5%","91.7%","95%"],"answer":2,"explanation":"Electricity access now covers 91.7% of the world, up from 84% in 2015. 45 countries have reached 100%.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-188","question":"Alexei Navalny died in:","options":["A Russian prison in February 2024","A car accident in 2023","In exile in Germany in 2024","A Ukrainian bombing in 2023"],"answer":0,"explanation":"Russia's most prominent opposition leader, Alexei Navalny, died in a Russian prison in February 2024.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-189","question":"The ASEAN Secretary-General's role is defined under:","options":["ASEAN Charter Article 5","ASEAN Charter Article 11","RCEP Agreement","The Bangkok Declaration"],"answer":1,"explanation":"The ASEAN Secretary-General's role as Chief Administrative Officer is defined under ASEAN Charter Article 11.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-190","question":"Lebanon's civilian displacement from the Israel-Hezbollah War reached:","options":["100,000+","500,000+","1.1 million+","2 million+"],"answer":2,"explanation":"By late March 2026, Israel's strikes deep into south Beirut displaced over 1.1 million Lebanese civilians.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-191","question":"Operation Absolute Resolve (January 2026) targeted:","options":["Iran's nuclear facilities","Al-Qaeda leadership","Venezuela's President Maduro","Hamas tunnels in Gaza"],"answer":2,"explanation":"On 3 January 2026, U.S. special operations forces launched Operation Absolute Resolve, seizing Venezuela's President Nicolas Maduro in Caracas.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-192","question":"What is the annual financing gap for achieving SDGs?","options":["$400 billion","$1 trillion","$2 trillion","$4 trillion"],"answer":3,"explanation":"The SDG Report identifies a $4 trillion annual financing gap as one of the main obstacles to achieving the SDGs by 2030.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-193","question":"The 2026 FIFA World Cup will feature how many teams?","options":["32","40","48","64"],"answer":2,"explanation":"The 2026 World Cup expands to 48 teams (from 32) and 104 matches total.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-194","question":"Which country's elections on 8 February 2026 included a constitutional referendum?","options":["Japan","Portugal","Thailand","Vietnam"],"answer":2,"explanation":"Thailand held both House of Representatives elections and a Constitutional Referendum on 8 February 2026.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-195","question":"Super Bowl LX (60) in February 2026 was held at:","options":["MetLife Stadium, New Jersey","SoFi Stadium, California","Levi's Stadium, California","AT&T; Stadium, Texas"],"answer":2,"explanation":"Super Bowl LX was held on 8 February 2026 at Levi's Stadium in California.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-196","question":"Dr. Kao Kim Hourn focuses on which priority areas as ASEAN Secretary-General?","options":["Military security and nuclear deterrence","AI, supply chains, and sustainable growth","Maritime law and fishing rights","Tourism and cultural exchange"],"answer":1,"explanation":"Dr. Kao Kim Hourn focuses on AI, supply chains, and sustainable growth.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-197","question":"The 2026 ASEAN Chair Philippines uses the theme:","options":["Epicentrum of Growth","Inclusivity and Sustainability","Navigating Our Future, Together","Enhancing Connectivity and Resilience"],"answer":2,"explanation":"The Philippines' 2026 ASEAN Chairmanship theme is 'Navigating Our Future, Together.'","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-198","question":"Which ASEAN country has a single-party communist government?","options":["Cambodia","Vietnam","Myanmar","Thailand"],"answer":1,"explanation":"Vietnam (along with Laos) operates under a single-party communist state where the Communist Party holds exclusive power.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-199","question":"The New START nuclear treaty expired in:","options":["2023","2024","February 2026","2027"],"answer":2,"explanation":"The New START treaty limiting U.S. and Russian strategic nuclear weapons expired in February 2026.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"base-200","question":"HFRS (Haemorrhagic Fever with Renal Syndrome) caused by Hantavirus primarily affects:","options":["Lungs and heart","Liver and spleen","Kidneys and blood vessels","Brain and nervous system"],"answer":2,"explanation":"HFRS occurs mainly in Europe and Asia, primarily affecting the kidneys and blood vessels. Multiple Choice Examination Hantavirus, Environmental Science & Global Events 2026 16 Questions • 4 Questions per Page • Choose the best answer for each question — Page 1 of 4 — 1. Hantaviruses are primarily transmitted to humans through which route? A. Direct contact with infected rodents B. Inhalation of aerosolized rodent droppings, urine, or saliva C. Consumption of contaminated food or water D. Bites from infected insects Correct Answer: B Explanation: Hantaviruses are zoonotic viruses transmitted mainly via inhalation of aerosolized droppings, urine, or saliva from infected rodent reservoirs — not by direct contact, food/water, or insect bites. 2. Which hantavirus strain is a notable exception because it can spread from person to person? A. Sin Nombre virus B. Seoul virus C. Andes virus D. Puumala virus Correct Answer: C Explanation: The Andes virus in South America is the only known hantavirus with documented limited person-to-person transmission through close contact. All other strains do not spread between humans. 3. Hantavirus Cardiopulmonary Syndrome (HCPS) is mainly found in which region and primarily affects which organ system? A. Europe and Asia — kidneys and blood vessels B. The Americas — lungs and heart C. Africa — liver and spleen D. Southeast Asia — nervous system Correct Answer: B Explanation: HCPS occurs in the Americas and targets the lungs and heart, carrying a fatality rate of up to 50%. HFRS (Haemorrhagic Fever with Renal Syndrome), which affects kidneys, is the form seen in Europe and Asia. 4. Which of the following best describes the current treatment approach for hantavirus infection? A. Specific antiviral drugs such as ribavirin are highly effective B. Vaccination is the primary preventive and curative measure C. Management is limited to early supportive care in an intensive care setting D. Antibiotics are prescribed to eliminate the virus Correct Answer: C Explanation: There are no specific antiviral treatments or approved vaccines for hantavirus. Management relies entirely on early, intensive supportive care. Antibiotics have no effect on viruses. — Page 2 of 4 — 5. Why is dry sweeping discouraged when cleaning areas contaminated with rodent droppings? A. It damages cleaning equipment B. It spreads bacteria to other surfaces C. It can aerosolize viral particles and increase inhalation risk D. It is ineffective at removing droppings Correct Answer: C Explanation: Dry sweeping can disturb dried droppings and make viral particles airborne. The recommended practice is to dampen contaminated areas first so that the virus cannot become airborne during cleaning. 6. According to the Kok River research, what percentage of the river's heavy-metal contamination originates from rare earth element (REE) mines? A. 30% B. 50% C. 70% D. 90% Correct Answer: C Explanation: Forensic analysis showed that 70% of contamination came from REE mines in Shan State, Myanmar, while 30% came from gold mines. The chemical fingerprint included arsenic, dysprosium, uranium, and thorium. 7. Which fish species is highlighted in the Kok River study as a key indicator of aquatic health due to toxic accumulation? A. Pangasius hypophthalmus B. Bagarius bagarius (Pla Khae) C. Oncorhynchus mykiss D. Clarias batrachus Correct Answer: B Explanation: Bagarius bagarius (Pla Khae) is a predator that lives in river sediment and accumulates high levels of toxins. The study found that toxic exposure weakens its immune system, making it susceptible to chronic infections and parasites. 8. What mining technique used in Myanmar is identified as a major cause of water pollution in the Kok River basin? A. Open-pit mining B. Underground tunnel blasting C. In-situ leaching D. Dredge mining Correct Answer: C Explanation: In-situ leaching involves injecting chemical solutions underground to dissolve minerals. This process severely pollutes surrounding water sources and was identified as the primary method used in the REE mines near the Thai border. — Page 3 of 4 — 9. What was the name of the U.S. military operation launched on January 3, 2026, that resulted in the arrest of Venezuelan President Nicolás Maduro? A. Operation Desert Storm B. Operation Absolute Resolve C. Operation Epic Fury D. Operation Iron Fist Correct Answer: B Explanation: Operation Absolute Resolve was the U.S. special-forces operation that seized Maduro at his residence in Caracas on January 3, 2026. Operation Epic Fury was the separate strike on Iran in February 2026. 10. Where was Nicolás Maduro taken after his arrest, and what charge did he face? A. Washington D.C. — espionage B. Miami — money laundering C. New York — narco-terrorism D. The Hague — crimes against humanity Correct Answer: C Explanation: Maduro was transported on USS Iwo Jima and flown to New York to face charges of narco-terrorism and possessing weapons threatening U.S. national security. He pleaded not guilty on January 5, calling himself a victim of kidnapping. 11. The 25th Winter Olympics were held in February 2026. Which cities hosted the event? A. Beijing and Zhangjiakou, China B. Oslo and Lillehammer, Norway C. Milan and Cortina d'Ampezzo, Italy D. Sapporo and Tokyo, Japan Correct Answer: C Explanation: The 25th Winter Olympics were held February 6–22, 2026, in Milan and Cortina d'Ampezzo, Italy. The previous Winter Olympics (2022) were in Beijing, China. 12. Thailand's February 8, 2026 national vote included which two simultaneous events? A. Senate elections and local government elections B. House of Representatives elections and a Constitutional Referendum C. Presidential elections and provincial elections D. Senate elections and a budget referendum Correct Answer: B Explanation: On February 8, 2026, Thailand held both House of Representatives elections and a Constitutional Referendum on the same day — a significant dual democratic event noted alongside elections in Japan, Portugal, Costa Rica, and Bangladesh. — Page 4 of 4 — 13. What immediate economic impact did Iran's retaliation in the Strait of Hormuz crisis have on oil prices? A. Prices fell from ~$103 to ~$70 per barrel B. Prices remained stable due to strategic reserves C. Prices surged from ~$70 to ~$103 per barrel D. Prices rose modestly from ~$70 to ~$80 per barrel Correct Answer: C Explanation: Iran's strikes on oil infrastructure and ships in the Strait of Hormuz caused commercial traffic to drop by over 90%, sending oil prices from approximately $70 to $103 per barrel in March 2026. Dubai International Airport was also temporarily closed due to drone attacks. 14. On April 1, 2026, NASA launched Artemis II. What record did the spacecraft break on April 6? A. Fastest crewed spacecraft to reach lunar orbit B. First spacecraft to land on the lunar south pole C. Farthest distance from Earth ever traveled by a crewed spacecraft D. Longest continuous human spaceflight beyond low-Earth orbit Correct Answer: C Explanation: On April 6, 2026, Artemis II surpassed the distance record set by Apollo 13 in 1970, making it the farthest any crewed spacecraft had traveled from Earth. The mission was the first crewed lunar flyby in 50 years. 15. Why did Moldova's parliament vote to withdraw from the Commonwealth of Independent States (CIS) in April 2026? A. Economic disputes over trade tariffs with member states B. Russia's violations of sovereignty principles C. Moldova's accession to the European Union D. Disagreements over CIS military obligations Correct Answer: B Explanation: On April 2, 2026, Moldova's parliament approved withdrawal from the CIS, citing Russia's violations of sovereignty principles. This decision reflected Moldova's broader geopolitical shift away from Russian influence. 16. Which countries brokered the April 2026 US-Iran ceasefire, and why was the subsequent meeting between VP JD Vance and Iran's parliamentary speaker historically significant? A. Qatar and Turkey; first direct talks since 2015 nuclear deal B. Pakistan and China; highest-level direct U.S.-Iran contact since the 1979 revolution C. Saudi Arabia and Russia; first ceasefire after the Strait of Hormuz crisis D. UAE and France; first meeting on Iranian soil since 2003 Correct Answer: B Explanation: The two-week ceasefire was brokered by Pakistan with a last-minute push from China. VP JD Vance then met Iran's parliamentary speaker in Islamabad — the highest-level direct U.S.-Iran contact since the 1979 Islamic Revolution, marking a dramatic diplomatic shift. Multiple Choice Examination Kok River Contamination — Environmental Science Focus 20 Questions • 4 Questions per Page • Choose the best answer for each question — Page 1 of 5 — 1. The Kok River contamination study found that the primary sources of pollution are mines located in which region? A. Chiang Rai Province, Thailand B. Shan State, Myanmar, approximately 25 km from the Thai border C. Yunnan Province, China D. Kachin State, Myanmar, over 100 km from the Thai border Correct Answer: B Explanation: Forensic evidence identified the primary pollution sources as mines in Shan State, Myanmar, approximately 25 kilometres from the Thai border — not within Thailand or other regions. 2. What percentage of the Kok River's contamination originates from rare earth element (REE) mines? A. 30% B. 50% C. 60% D. 70% Correct Answer: D Explanation: 70% of the contamination originates from REE mines, while the remaining 30% comes from gold mines. The study used chemical fingerprinting to determine these proportions. 3. What percentage of the Kok River's contamination comes from gold mines? A. 10% B. 20% C. 30% D. 40% Correct Answer: C Explanation: Gold mines account for 30% of the contamination. The remaining 70% is attributed to rare earth element (REE) mines in Shan State, Myanmar. 4. Which chemical elements form the 'fingerprint' used to trace the Kok River contamination back to REE mines in Myanmar's Kachin State? A. Lead, mercury, cadmium, and chromium B. Arsenic, dysprosium, uranium, and thorium C. Copper, zinc, nickel, and manganese D. Iron, cobalt, selenium, and barium Correct Answer: B Explanation: Researchers identified a chemical fingerprint comprising arsenic, dysprosium, uranium, and thorium that matched the wastewater profile of REE mines in Myanmar's Kachin State, providing forensic evidence of the pollution source. — Page 2 of 5 — 5. What mining technique used in Myanmar is identified as the major cause of water pollution in the Kok River basin? A. Open-pit mining B. Underground tunnel blasting C. In-situ leaching D. Hydraulic dredging Correct Answer: C Explanation: In-situ leaching involves injecting chemical solutions underground to dissolve minerals. This process severely pollutes surrounding groundwater and surface water sources, and was identified as the primary extraction method used in the REE mines. 6. How many people are estimated to depend on the Kok River system and are therefore at risk from contamination? A. Over 100,000 B. Over 500,000 C. Over 1,000,000 D. Over 5,000,000 Correct Answer: C Explanation: The study states that over one million people depend on the Kok River system, making the contamination a serious public health concern at a regional scale. 7. Which fish species is highlighted in the Kok River study as a key bioindicator of toxic contamination? A. Pangasius hypophthalmus (Pla Sawai) B. Bagarius bagarius (Pla Khae) C. Clarias batrachus (Pla Duk) D. Oncorhynchus mykiss (Rainbow trout) Correct Answer: B Explanation: Bagarius bagarius, known locally as Pla Khae, is a bottom-dwelling predator that accumulates high levels of toxins from river sediment. Its health status serves as a key indicator of overall river ecosystem health. 8. What health problems were found in Bagarius bagarius (Pla Khae) fish in the Kok River? A. Tumours on the skin and loss of scales only B. Chronic infections, parasites, and internal inflammation C. Reproductive failure and abnormal skeletal growth D. Blindness and loss of lateral line function Correct Answer: B Explanation: Research found that Bagarius bagarius suffered from chronic infections, parasites, and internal inflammation. Scientists confirmed that toxic exposure weakens the fish's immune system, making them susceptible to these ailments — previously thought to be simple disease. — Page 3 of 5 — 9. What is the current mercury level found in Bagarius bagarius fish meat, and why is this concerning for children? A. 0.10 mg/kg — already exceeds the safety threshold for children B. 0.25 mg/kg — nearing the children's safety threshold of 0.30 mg/kg C. 0.50 mg/kg — twice the safety threshold for adults D. 0.05 mg/kg — still well within safe limits for all groups Correct Answer: B Explanation: Mercury was measured at 0.25 mg/kg in fish meat, approaching but not yet exceeding the safety threshold of 0.30 mg/kg for children. While still within standard limits, this proximity to the threshold raises long-term concern, especially for children who consume fish regularly. 10. Why is Bagarius bagarius (Pla Khae) particularly susceptible to high levels of toxic accumulation compared to other fish? A. It breathes air and absorbs pollutants directly from the atmosphere B. It is a predator that lives in river sediment, concentrating toxins through biomagnification C. It reproduces slowly, giving toxins more time to accumulate in each individual D. It lacks a liver, so it cannot detoxify pollutants Correct Answer: B Explanation: As a predator living in river sediment, Bagarius bagarius is exposed to high sediment toxin concentrations and accumulates toxins from its prey through biomagnification — the process by which toxin concentrations increase at each level of the food chain. 11. What does the term 'biomagnification' mean in the context of the Kok River study? A. The rapid reproduction of toxic bacteria in warm river water B. The process by which toxin concentrations increase at higher levels of the food chain C. The enlargement of fish organs due to prolonged toxic exposure D. The spread of pollutants downstream through water currents Correct Answer: B Explanation: Biomagnification refers to the progressive increase in toxin concentration as one moves up the food chain. Because Bagarius bagarius is a top predator, it accumulates higher toxin loads than organisms lower in the food web, potentially passing these toxins to humans who consume the fish. 12. How much agricultural land in Chiang Rai depends on the Kok River? A. Over 10,000 rai B. Over 50,000 rai C. Over 100,000 rai D. Over 500,000 rai Correct Answer: C Explanation: The study notes that over 100,000 rai of agricultural land in Chiang Rai Province depends on the Kok River for irrigation and water supply, making agricultural contamination a significant concern for food security. — Page 4 of 5 — 13. What do current tests show regarding contamination levels in groundwater and vegetables in communities near the Kok River? A. Contamination has already reached dangerous levels in both groundwater and vegetables B. Contamination has not yet reached dangerous levels for humans, but long-term accumulation is a concern C. Groundwater is safe but vegetables show critically high toxin levels D. All tested sources are completely free from contamination Correct Answer: B Explanation: Current tests show that contamination in groundwater and vegetables has not yet reached dangerous levels for humans. However, experts warn that long-term accumulation could lead to significant health issues and weakened immunity in the future. 14. What long-term health consequences do experts warn about for communities that continue to depend on the Kok River? A. Acute poisoning events from sudden toxin spikes B. Significant health issues and weakened immunity from gradual toxin accumulation C. Respiratory diseases caused by airborne REE particles D. Skin diseases from direct water contact only Correct Answer: B Explanation: While immediate toxin levels in food and water are not yet at critical thresholds, experts caution that long-term accumulation of heavy metals and REEs could lead to significant health issues, including weakened immune systems, in affected communities. 15. How did local activists characterise the Kok River pollution in terms of accountability? A. A natural geological phenomenon requiring scientific monitoring B. A regional environmental crime requiring urgent accountability from polluters and mineral buyers C. A temporary industrial accident that will resolve over time D. A domestic Thai environmental issue unrelated to cross-border mining Correct Answer: B Explanation: Local activists criticised the government for lack of transparency and delays in negotiations, calling the pollution a 'regional environmental crime' that demands urgent accountability from both the polluters and the companies that purchase the extracted minerals. 16. The Kok River contamination originates from mines in Shan State, Myanmar. Approximately how far are these mines from the Thai border? A. 5 kilometres B. 15 kilometres C. 25 kilometres D. 50 kilometres Correct Answer: C Explanation: Forensic evidence places the primary mine sources approximately 25 kilometres from the Thai border in Shan State, Myanmar. This proximity means that polluted water flows cross-border into the Kok River system in Thailand. — Page 5 of 5 — 17. Although metal levels in Bagarius bagarius fish meat are currently within standard safety limits, what specific concern is highlighted regarding mercury? A. Mercury levels are rising rapidly and expected to exceed safe limits within one year B. Mercury at 0.25 mg/kg is approaching the 0.30 mg/kg threshold considered safe for children C. Mercury has bioaccumulated to levels that are toxic to adult humans D. Mercury levels are undetectable but other heavy metals are at critical levels Correct Answer: B Explanation: The study specifically highlights that mercury levels at 0.25 mg/kg are nearing the 0.30 mg/kg safety threshold set for children, indicating a particular risk for younger consumers of Pla Khae even though overall metal levels are technically within general standards. 18. What is the primary reason the Kok River contamination is described as a 'cross-border' environmental problem? A. The river flows through three countries and affects all equally B. Mines in Myanmar pollute water that flows into Thailand, affecting communities across the border C. Thailand and Myanmar jointly operate the mines causing the contamination D. International shipping vessels dump waste in the river at the border crossing Correct Answer: B Explanation: The contamination is cross-border because mines in Shan State, Myanmar (approximately 25 km from the Thai border) release pollutants into water systems that flow into the Kok River in Thailand, harming Thai communities and ecosystems downstream. 19. What criticism did local activists direct at the Thai government regarding the Kok River contamination? A. Failure to invest in water treatment infrastructure B. Lack of transparency and delays in negotiations with Myanmar C. Allowing Thai companies to profit from the contaminating mines D. Removing fishing rights from local communities without compensation Correct Answer: B Explanation: Local activists criticised the government specifically for a lack of transparency and slow progress in negotiations — implying that diplomatic or legal steps to address the cross-border source of pollution have been insufficient or delayed. 20. Based on the Kok River study, which of the following best summarises the overall risk to human health? A. Immediate acute poisoning is occurring in all communities along the river B. There is no risk since all measured levels are within safety standards C. Current levels are below thresholds but long-term accumulation poses future health risks, especially to children D. Risk is limited only to communities that eat fish daily Correct Answer: C Explanation: The study presents a nuanced picture: current contamination in food and water has not yet reached acutely dangerous levels, but long-term bioaccumulation — especially of mercury approaching children's safety thresholds — means the future health risk is real and warrants urgent preventive action and cross-border accountability. @WORKMANDEE Do not forward! 12 Updated Practice Questions with Answers & Explanations - Updated July 2026 1. The 2026 FIFA World Cup is being co-hosted by which countries? A. Brazil, Argentina, Uruguay B. United States, Canada, Mexico C. Qatar, Saudi Arabia, UAE D. Germany, France, Spain Explanation: The 2026 FIFA World Cup runs from June 11 to July 19, 2026, co-hosted by the United States, Canada, and Mexico - the first tournament ever with three host nations. It is also the first edition expanded from 32 to 48 teams, and Mexico becomes the first country to host the World Cup three times. 2. The Amazon Rainforest spans 9 countries. Which country listed below is NOT one of them? A. Peru B. Colombia C. Venezuela D. Mexico Explanation: The Amazon Rainforest covers 9 countries: Brazil, Peru, Colombia, Venezuela, Ecuador, Bolivia, Guyana, Suriname, and French Guiana (a French territory). Brazil holds the largest share, over 60% of the forest. Mexico lies outside the Amazon basin. 3. Which of the following territories is NOT a sovereign state and UN member? A. Singapore B. Hong Kong C. Brunei D. Timor-Leste Explanation: Hong Kong is a Special Administrative Region of the People's Republic of China, governed with a degree of autonomy under the \"one country, two systems\" principle. It is not a sovereign state and holds no seat at the United Nations. 4. Who currently serves as Prime Minister of Italy? A. Mario Draghi B. Giuseppe Conte C. Giorgia Meloni D. Sergio Mattarella Explanation: Giorgia Meloni has served as Prime Minister of Italy since 2022, the country's first female head of government. Sergio Mattarella, by contrast, holds the largely ceremonial role of President (head of state). 5. Who is the current President of the United States (the 47th)? A. Joe Biden B. Donald Trump C. Kamala Harris D. Barack Obama Explanation: Donald Trump won the 2024 U.S. presidential election and was sworn in as the 47th President of the United States in January 2025. 6. Who currently serves as President of Iran? A. Ebrahim Raisi B. Hassan Rouhani C. Ali Khamenei D. Masoud Pezeshkian Explanation: Masoud Pezeshkian has served as President of Iran (head of government) since 2024, following the death of Ebrahim Raisi. Ali Khamenei remains Iran's Supreme Leader (head of state), a position he has held since 1989. 7. Who currently serves as President of Ukraine? A. Petro Poroshenko B. Volodymyr Zelensky C. Viktor Yanukovych D. Yulia Tymoshenko Explanation: Volodymyr Zelensky has served as President of Ukraine since 2019 and remains in office amid the prolonged war with Russia that began in 2022. 8. Which river is the longest in the world? A. Amazon River B. Nile River C. Yangtze River D. Mississippi River Explanation: The Nile River in Africa, at roughly 6,650 km, is generally considered the longest river in the world, flowing through 11 countries. The Amazon River in South America ranks a close second in length but carries by far the largest volume of water of any river on Earth. 9. In the ASEAN context, the term \"CLMV\" refers to which group of countries? A. Cambodia, Laos, Myanmar, Vietnam B. China, Laos, Malaysia, Vietnam C. Cambodia, Laos, Malaysia, Vietnam D. Cambodia, Laos, Myanmar, Philippines Explanation: CLMV stands for Cambodia, Laos, Myanmar, and Vietnam - the ASEAN member states that joined later and are grouped as the bloc's less-developed economies, generally lagging behind the founding ASEAN members in economic development. 10. What is the term for the phenomenon in which sea surface temperatures in the central and eastern Pacific Ocean become abnormally warm? A. La Nina B. El Nino C. Monsoon D. Greenhouse Effect Explanation: El Nino is a climate pattern in which sea surface temperatures in the central and eastern equatorial Pacific rise above normal, triggering weather disruptions worldwide - including drought in some regions and heavy rainfall in others. It is the opposite phase of La Nina, when those waters cool below normal. 11. The term \"global boiling,\" used by the UN Secretary-General, is most closely associated with which of the following? A. Global warming and record-high ocean temperatures B. Undersea volcanic eruptions C. Tsunamis D. Freshwater scarcity Explanation: \"Global boiling\" was used to underscore the severity of global warming and ocean warming, as sea surface temperatures worldwide reached record highs - harming marine ecosystems, driving coral bleaching, and intensifying storms. 12. Which ASEAN member state is landlocked (has no coastline)? A. Cambodia B. Laos C. Myanmar D. Vietnam Explanation: Laos is the only landlocked country in ASEAN, bordered by China, Myanmar, Thailand, Cambodia, and Vietnam.","source":"เอกสารชุดฝึก 200 ข้อพร้อมเฉลย"},{"id":"news-001","question":"What is the name of the 2026 conflict between the US-Israel and Iran?","options":["The 2026 Iran War","The Third Persian Gulf War","The Syrian Crisis","The New Cold War"],"answer":0,"explanation":"The escalating confrontation between the US, Israel, and Iran throughout 2026 is referred to as the 2026 Iran War.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-002","question":"In which month was the temporary ceasefire memorandum between the US and Iran signed?","options":["May 2026","June 2026","July 2026","August 2026"],"answer":1,"explanation":"The US and Iran signed a temporary ceasefire memorandum in June 2026 in an attempt to halt hostilities.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-003","question":"Why did the ceasefire agreement collapse?","options":["Iran resumed attacks on commercial ships in the Strait of Hormuz","The US unilaterally withdrew from the agreement","Israel struck Tehran","The United Nations cancelled the agreement"],"answer":0,"explanation":"The ceasefire fell apart after Iran resumed attacking commercial vessels transiting the Strait of Hormuz.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-004","question":"In which month did the ceasefire agreement collapse?","options":["June 2026","July 2026","August 2026","September 2026"],"answer":1,"explanation":"The ceasefire, signed in June, collapsed the following month in July 2026.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-005","question":"During which period did the energy crisis in the Strait of Hormuz intensify?","options":["June-July","July-August","August-September","September-October"],"answer":2,"explanation":"Retaliatory measures between the US and Iran escalated sharply between August and September 2026.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-006","question":"What was the effect of the Strait of Hormuz crisis on global crude oil prices?","options":["Oil prices fell to a 5-year low","Oil prices surged toward nearly $100 per barrel","Oil prices remained unchanged","Global oil trading was suspended"],"answer":1,"explanation":"Shipping through Hormuz dropped to record lows, pushing crude oil prices close to $100 per barrel.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-007","question":"What target did Iran threaten to attack in the US?","options":["Naval bases","Oil reserves","Embassies","Satellites"],"answer":1,"explanation":"Iran threatened to strike US oil reserves in retaliation for tightened economic sanctions.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-008","question":"Which country warned of a possible \"industrial catastrophe\" if the Iran crisis continues?","options":["Saudi Arabia","Qatar","United Arab Emirates","Kuwait"],"answer":1,"explanation":"Qatar warned that a prolonged crisis could trigger an \"industrial catastrophe\" in the region.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-009","question":"In June 2026, Ukraine launched its largest attack on Moscow using which weapon?","options":["Missiles","Drones","Artillery","Submarines"],"answer":1,"explanation":"Ukraine carried out its largest drone attack on Moscow since the war began.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-010","question":"Russia continued to strike infrastructure in which Ukrainian city?","options":["Kharkiv","Odesa","Kyiv","Lviv"],"answer":2,"explanation":"Russia kept up heavy strikes on infrastructure in the capital, Kyiv.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-011","question":"Russia pushed its northern front line in which area during August-September 2026?","options":["Kyiv","Kharkiv","Odesa","Crimea"],"answer":1,"explanation":"Russian forces pressed their offensive along the northern front near Kharkiv.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-012","question":"Which US envoys traveled to Moscow in early September 2026 to revive peace talks?","options":["Steve Witkoff and Jared Kushner","Antony Blinken and Jake Sullivan","Marco Rubio and Mike Waltz","Elon Musk and Vivek Ramaswamy"],"answer":0,"explanation":"US envoys Steve Witkoff and Jared Kushner traveled to Moscow to restart peace negotiations.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-013","question":"President Zelensky stated that Russia's attitude toward negotiations was:","options":["Completely refusing to negotiate","More willing to negotiate","Issuing an ultimatum for Ukraine to surrender","Requesting to postpone talks until next year"],"answer":1,"explanation":"Zelensky said Russia appeared \"more ready to negotiate\" following the renewed diplomatic push.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-014","question":"What kind of relationship did the US and China show signs of in 2026?","options":["Escalating tensions","Détente (easing of tensions)","Cutting diplomatic ties","Declaring a full-scale trade war"],"answer":1,"explanation":"The US and China showed signs of détente, working to ease trade and AI-related tensions.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-015","question":"Where is the planned summit between Xi Jinping and Donald Trump scheduled to take place?","options":["Beijing","Washington, D.C.","Geneva","Singapore"],"answer":1,"explanation":"The Xi-Trump summit was being prepared for Washington, D.C. in late September 2026.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-016","question":"Where was the 2026 G7 Summit held?","options":["Italy","Germany","France","Japan"],"answer":2,"explanation":"The 2026 G7 Summit was hosted by France in June.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-017","question":"Where was the 2026 NATO Summit held?","options":["Belgium","Turkey","Poland","Spain"],"answer":1,"explanation":"The 2026 NATO Summit took place in Turkey in July.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-018","question":"Which session of the UN General Assembly convened in September 2026?","options":["The 78th session","The 79th session","The 80th session","The 81st session"],"answer":3,"explanation":"The 81st session of the UN General Assembly opened in September 2026.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-019","question":"Where was the 81st UN General Assembly held?","options":["Geneva","New York City","Vienna","Paris"],"answer":1,"explanation":"As always, the UN General Assembly convened at UN Headquarters in New York City.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-020","question":"How much was Canada's retaliatory tariff measure against the US worth in September 2026?","options":["$10 billion","$20 billion","$30 billion","$50 billion"],"answer":1,"explanation":"Canada announced roughly $20 billion in retaliatory tariffs against the US.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-021","question":"Which aircraft manufacturer did Trump threaten to block sales of unless produced in America?","options":["Boeing","Airbus","Bombardier","Embraer"],"answer":2,"explanation":"Trump threatened to block Bombardier jet sales unless production moved to the United States.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-022","question":"What type of weapons was the Pentagon ordered to overhaul its policy on in June 2026?","options":["Nuclear weapons","Autonomous weapons","Chemical weapons","Cyber weapons"],"answer":1,"explanation":"The Pentagon was ordered to overhaul its guidance on autonomous (AI-driven) weapons.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-023","question":"The Pentagon is accelerating AI warfare technology to counter challenges from which country?","options":["Russia","North Korea","China","Iran"],"answer":2,"explanation":"The push to accelerate autonomous weapons technology was framed as countering China.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-024","question":"In which city was the global tech conference LEAP 2026 held?","options":["Dubai","Abu Dhabi","Riyadh","Doha"],"answer":2,"explanation":"LEAP 2026, a major global technology conference, was held in Riyadh, Saudi Arabia.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-025","question":"On what date did the LEAP 2026 conference conclude?","options":["September 1, 2026","September 3, 2026","September 5, 2026","September 8, 2026"],"answer":1,"explanation":"LEAP 2026 concluded on September 3, 2026.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-026","question":"What area did LEAP 2026 primarily focus its investment on?","options":["Renewable energy","Artificial Intelligence (AI) and Cloud Computing","Tourism","Automotive industry"],"answer":1,"explanation":"The conference centered on massive investment commitments in AI and cloud computing.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-027","question":"Which organization issued a warning about an intensifying El Niño?","options":["UNEP","WMO (World Meteorological Organization)","IPCC","NASA"],"answer":1,"explanation":"The World Meteorological Organization (WMO) issued the warning about a strengthening El Niño.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-028","question":"What effect will the intensifying El Niño have on many regions worldwide?","options":["Temperatures will drop below normal","Temperatures will rise above normal later in the year","Rainfall will decrease globally","There will be no clear impact"],"answer":1,"explanation":"WMO warned the strong El Niño would push temperatures above normal in many regions later in the year.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-029","question":"What is the name of the volcano that erupted in Indonesia in early September 2026?","options":["Mount Merapi","Anak Krakatau","Mount Sinabung","Mount Bromo"],"answer":1,"explanation":"Indonesia's Anak Krakatau volcano erupted in early September 2026.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-030","question":"What was the impact of the Anak Krakatau eruption?","options":["8 airports closed and over 2,300 flights cancelled","A major tsunami across the Indian Ocean","Over 1 million people permanently displaced","It triggered an 8.0 magnitude earthquake"],"answer":0,"explanation":"Volcanic ash forced the closure of 8 airports and the cancellation of more than 2,300 flights.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-031","question":"Who is the current Prime Minister of Japan (as of September 2026)?","options":["Fumio Kishida","Shigeru Ishiba","Sanae Takaichi","Yoshihide Suga"],"answer":2,"explanation":"Sanae Takaichi has served as Japan's Prime Minister since October 2025.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-032","question":"When did Sanae Takaichi take office as Prime Minister of Japan?","options":["October 21, 2025","October 21, 2026","January 1, 2026","September 27, 2025"],"answer":0,"explanation":"Takaichi took office as Prime Minister of Japan on October 21, 2025.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-033","question":"What makes Sanae Takaichi historic in Japanese politics?","options":["The youngest prime minister ever","The first female prime minister of Japan","The longest-serving prime minister","The first prime minister from an opposition party"],"answer":1,"explanation":"Takaichi is Japan's first female prime minister.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-034","question":"Which political party does Takaichi belong to?","options":["Constitutional Democratic Party","Liberal Democratic Party (LDP)","Komeito","Japan Innovation Party"],"answer":1,"explanation":"Takaichi leads the ruling Liberal Democratic Party (LDP).","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-035","question":"When does Takaichi plan to reshuffle her Cabinet in 2026?","options":["Early September","Mid-to-late September","Early October","Late December"],"answer":1,"explanation":"Takaichi planned her first Cabinet reshuffle for mid-to-late September 2026.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-036","question":"Which former Prime Minister did Takaichi succeed after his resignation?","options":["Fumio Kishida","Yoshihide Suga","Shigeru Ishiba","Shinzo Abe"],"answer":2,"explanation":"Takaichi succeeded Shigeru Ishiba, who resigned as PM in 2025.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-037","question":"The severe flooding in Nepal in late August-September 2026 occurred mainly along which rivers?","options":["The Ganges River","The Bhotekoshi and Trishuli Rivers","The Brahmaputra River","The Indus River"],"answer":1,"explanation":"The flooding was driven by the Bhotekoshi and Trishuli river systems.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-038","question":"Which Nepali agency reported the death toll from the flooding?","options":["NDRRMA","UNFPA","WHO","NDMA"],"answer":0,"explanation":"Nepal's National Disaster Risk Reduction and Management Authority (NDRRMA) reported the death toll.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-039","question":"The Nepal flooding also caused cross-border impacts in which country?","options":["India","Bangladesh","China (Xizang/Tibet Autonomous Region)","Bhutan"],"answer":2,"explanation":"The same storm system triggered deadly mudslides across the border in China's Xizang (Tibet) region.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-040","question":"Approximately how many people were affected by the Nepal floods, according to UN figures?","options":["About 50,000 people","About 84,270 people","About 150,000 people","About 500,000 people"],"answer":1,"explanation":"The UN estimated about 84,270 people were affected across 17 municipalities.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-041","question":"Who is the UN Resident Coordinator in Nepal who spoke about the situation?","options":["Lila Pieters Yahia","Antonio Guterres","Filippo Grandi","Achim Steiner"],"answer":0,"explanation":"Lila Pieters Yahia, the UN Resident Coordinator in Nepal, briefed media on relief efforts.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-042","question":"Which country's leader confirmed that some of its missing citizens in Nepal were found safe?","options":["India","Australia","United Kingdom","United States"],"answer":1,"explanation":"Australian PM Anthony Albanese confirmed several missing Australians had been found safe.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-043","question":"What is the estimated economic damage from the flooding in the Bhotekoshi area, according to NDRRMA?","options":["Rs 100 billion","Rs 400 billion","Rs 700 billion","Rs 1,000 billion"],"answer":1,"explanation":"NDRRMA estimated losses of approximately Rs 400 billion from the Bhotekoshi floods.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-044","question":"Which population group did UNFPA identify as especially affected by the Nepal floods?","options":["The elderly","Women of reproductive age and pregnant women","Business owners","Foreign tourists"],"answer":1,"explanation":"UNFPA flagged women of reproductive age, including thousands of pregnant women, as especially vulnerable.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-045","question":"Which of the following was considered the hottest geopolitical issue in mid-2026?","options":["The US-Canada trade war","The 2026 Iran War","The volcanic eruption in Indonesia","The election in Japan"],"answer":1,"explanation":"The 2026 Iran War was described as the hottest and most economically disruptive geopolitical flashpoint of the period.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-046","question":"Which of the following is NOT part of the planned US-China cooperation framework?","options":["Reducing trade conflicts","Managing AI-related risks","Preparing for the Xi-Trump summit","Jointly abolishing nuclear weapons"],"answer":3,"explanation":"The framework covers trade, AI risk management, and summit preparations — not nuclear disarmament.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-047","question":"Which of the following correctly orders the international summits by date?","options":["G7 Summit (France) → NATO Summit (Turkey) → 81st UNGA","NATO Summit → G7 Summit → UNGA","UNGA → G7 Summit → NATO Summit","NATO Summit → UNGA → G7 Summit"],"answer":0,"explanation":"Chronologically: G7 in France (June) came first, then NATO in Turkey (July), then the 81st UNGA (September).","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-048","question":"Which of the following relates to the \"energy crisis\" mentioned in the news?","options":["The volcanic eruption in Indonesia","The Strait of Hormuz crisis","The flooding in Nepal","Japan's Cabinet reshuffle"],"answer":1,"explanation":"The Strait of Hormuz crisis was the energy-related story, driving oil prices sharply higher.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-049","question":"Which event in the news is directly related to climate change?","options":["The Russia-Ukraine war","The WMO's warning about El Niño","The North American trade war","The LEAP 2026 conference"],"answer":1,"explanation":"WMO's warning about an intensifying El Niño is the item directly tied to climate patterns.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"news-050","question":"Which of the following belongs to the category of \"natural disasters\"?","options":["The Nepal floods and the Anak Krakatau eruption","The 2026 Iran War","The US-Canada trade war","The G7 Summit"],"answer":0,"explanation":"The Nepal floods and the Anak Krakatau volcanic eruption are natural disasters; the other options are geopolitical or economic events.","source":"แบบทดสอบข่าว มิ.ย.-ก.ย. 2026 พร้อมเฉลย"},{"id":"extra-001","question":"Which document is associated with ASEAN’s founding in Bangkok?","options":["Bangkok Declaration","Manila Treaty","Jakarta Protocol","Bali Concord"],"answer":0,"explanation":"The Bangkok Declaration established ASEAN in 1967.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-002","question":"Which set lists the five founding members of ASEAN?","options":["Indonesia, Malaysia, Philippines, Singapore, Thailand","Brunei, Cambodia, Laos, Myanmar, Vietnam","Indonesia, Brunei, Laos, Thailand, Vietnam","Malaysia, Myanmar, Philippines, Cambodia, Singapore"],"answer":0,"explanation":"The five founding members signed the Bangkok Declaration in 1967.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-003","question":"Where is the ASEAN Secretariat headquartered?","options":["Manila","Bangkok","Jakarta","Kuala Lumpur"],"answer":2,"explanation":"The ASEAN Secretariat is in Jakarta, Indonesia.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-004","question":"After Timor-Leste’s accession, how many ASEAN member states are there?","options":["9","10","11","12"],"answer":2,"explanation":"Timor-Leste became the eleventh member in October 2025.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-005","question":"Which country became ASEAN’s newest member in 2025?","options":["Papua New Guinea","Timor-Leste","Bangladesh","Sri Lanka"],"answer":1,"explanation":"Timor-Leste joined ASEAN on 26 October 2025.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-006","question":"Which country chairs ASEAN in 2026?","options":["Philippines","Malaysia","Thailand","Singapore"],"answer":0,"explanation":"The Philippines holds the 2026 ASEAN Chairmanship.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-007","question":"What is the Philippines’ 2026 ASEAN chair theme?","options":["One Vision, One Identity, One Community","Navigating Our Future, Together","Inclusivity and Sustainability","ASEAN Matters: Epicentrum of Growth"],"answer":1,"explanation":"The 2026 theme is “Navigating Our Future, Together.”","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-008","question":"The “2C” approach of the ASEAN Way refers to:","options":["Consultation and consensus","Cooperation and competition","Coordination and control","Commerce and connectivity"],"answer":0,"explanation":"Consultation and consensus are the two commonly tested process terms.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-009","question":"Which ASEAN principle discourages states from intervening in one another’s domestic affairs?","options":["Non-interference","Collective defense","Open skies","Common currency"],"answer":0,"explanation":"Non-interference is a central principle of ASEAN’s diplomatic approach.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-010","question":"In the ASEAN Way, self-restraint is intended to:","options":["Reduce confrontation and prevent escalation","Create a common ASEAN army","Replace national governments","Set a regional currency"],"answer":0,"explanation":"Self-restraint encourages peaceful conduct and avoidance of confrontation.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-011","question":"How does ASEAN normally rotate its chairmanship?","options":["By GDP rank","Alphabetically by English country name","By population","By order of accession"],"answer":1,"explanation":"The chairmanship rotates annually by the English alphabetical order of member states.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-012","question":"According to regular practice, how often does the ASEAN Summit meet?","options":["Once every two years","Once a year","Twice a year","Every month"],"answer":2,"explanation":"ASEAN Summit meetings are held twice annually.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-013","question":"Which ASEAN pillar focuses most directly on economic integration?","options":["AEC","APSC","ASCC","AICHR"],"answer":0,"explanation":"The ASEAN Economic Community (AEC) covers regional economic cooperation.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-014","question":"Which ASEAN pillar focuses on political and security cooperation?","options":["AEC","APSC","ASCC","AFTA"],"answer":1,"explanation":"The ASEAN Political-Security Community (APSC) addresses political and security matters.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-015","question":"Which ASEAN pillar focuses on social development, education, culture, and community well-being?","options":["AEC","APSC","ASCC","ARF"],"answer":2,"explanation":"The ASEAN Socio-Cultural Community (ASCC) covers people-centered social and cultural cooperation.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-016","question":"AFTA was designed primarily to:","options":["Facilitate freer trade in goods within ASEAN","Create a regional military alliance","Set a single ASEAN passport","Replace the ASEAN Summit"],"answer":0,"explanation":"The ASEAN Free Trade Area aims to lower barriers to regional goods trade.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-017","question":"ASEAN+3 adds which three partners to ASEAN cooperation?","options":["China, Japan, South Korea","India, Australia, New Zealand","Russia, United States, Canada","France, Germany, United Kingdom"],"answer":0,"explanation":"ASEAN+3 consists of China, Japan, and South Korea.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-018","question":"Which group of partners is added in the ASEAN+6 framework beyond ASEAN+3?","options":["India, Australia, New Zealand","Russia, United States, Canada","Pakistan, Bangladesh, Sri Lanka","France, Germany, Italy"],"answer":0,"explanation":"ASEAN+6 adds India, Australia, and New Zealand to ASEAN+3.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-019","question":"The abbreviation CLMV refers to which four ASEAN countries?","options":["Cambodia, Laos, Myanmar, Vietnam","China, Laos, Malaysia, Vietnam","Cambodia, Laos, Malaysia, Vietnam","Cambodia, Indonesia, Myanmar, Vietnam"],"answer":0,"explanation":"CLMV is shorthand for Cambodia, Laos, Myanmar, and Vietnam.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-020","question":"Which ASEAN member is landlocked?","options":["Laos","Thailand","Malaysia","Philippines"],"answer":0,"explanation":"Laos is the only landlocked ASEAN member.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-021","question":"Which group includes ASEAN states that share a land border with China?","options":["Myanmar, Laos, Vietnam","Indonesia, Malaysia, Singapore","Thailand, Cambodia, Brunei","Philippines, Indonesia, Timor-Leste"],"answer":0,"explanation":"Myanmar, Laos, and Vietnam border China.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-022","question":"RCEP combines ASEAN with which five partner economies?","options":["China, Japan, South Korea, Australia, New Zealand","India, Pakistan, Bangladesh, Nepal, Bhutan","United States, Canada, Mexico, Chile, Peru","France, Germany, Italy, Spain, Portugal"],"answer":0,"explanation":"RCEP’s 15 signatories are the ten original ASEAN parties plus five partners.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-023","question":"The Digital Economy Framework Agreement (DEFA) is aimed at strengthening:","options":["ASEAN digital economy cooperation","A shared ASEAN defense command","A common agricultural currency","Joint management of the UN Security Council"],"answer":0,"explanation":"DEFA is a regional framework for digital economy cooperation.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-024","question":"In the ASEAN Charter, Article 31 is commonly associated with:","options":["ASEAN chairmanship rotation","The ASEAN flag design","A common currency","A permanent regional army"],"answer":0,"explanation":"The attached study notes identify Article 31 with chairmanship rotation.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-025","question":"Mutual Recognition Arrangements (MRAs) mainly help ASEAN professionals by:","options":["Recognizing qualifications across participating countries","Guaranteeing identical salaries","Removing all national licensing rules","Creating a single university system"],"answer":0,"explanation":"MRAs make it easier to recognize qualifications for selected professions across borders.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-026","question":"A dispute over maritime claims in the South China Sea is most closely linked to which ASEAN pillar?","options":["APSC","AEC","ASCC","ASEAN Secretariat"],"answer":0,"explanation":"The issue is primarily political and security-related.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-027","question":"The Rohingya displacement issue is often discussed as a regional concern involving:","options":["Refugees and human rights","A common ASEAN currency","Nuclear energy sharing","Space exploration"],"answer":0,"explanation":"The materials connect the issue with displacement, refugees, and human rights.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-028","question":"Why can ASEAN’s non-interference principle complicate a response to crises inside a member state?","options":["It limits direct involvement in domestic affairs","It requires every member to use force","It bans humanitarian assistance","It transfers national sovereignty to the UN"],"answer":0,"explanation":"The principle can make collective action on internal crises more difficult.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-029","question":"Transboundary haze is called transboundary because it:","options":["Can cross national borders and affect neighboring states","Occurs only inside one city","Is caused only by ocean currents","Cannot be monitored by satellites"],"answer":0,"explanation":"Smoke and air pollution can travel across borders and affect multiple countries.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-030","question":"Which is a clear example of non-traditional security?","options":["Human trafficking across borders","A change in ASEAN’s meeting venue","A national flag redesign","A routine diplomatic reception"],"answer":0,"explanation":"Human trafficking is a non-traditional security challenge.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-031","question":"The Universal Declaration of Human Rights was adopted in:","options":["1945","1948","1955","1967"],"answer":1,"explanation":"The UN General Assembly adopted the UDHR on 10 December 1948.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-032","question":"How many articles are in the Universal Declaration of Human Rights?","options":["17","24","30","42"],"answer":2,"explanation":"The UDHR contains 30 articles.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-033","question":"Which right is protected by Article 5 of the UDHR?","options":["Protection from torture and degrading treatment","The right to vote in every country","The right to own a company","The right to change national borders"],"answer":0,"explanation":"Article 5 prohibits torture and cruel, inhuman, or degrading treatment.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-034","question":"Freedom of opinion and expression is addressed in which UDHR article?","options":["Article 3","Article 5","Article 18","Article 19"],"answer":3,"explanation":"Article 19 protects freedom of opinion and expression.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-035","question":"UDHR Article 3 protects the right to:","options":["Life, liberty, and security of person","Free international trade","A permanent seat on the Security Council","A national language"],"answer":0,"explanation":"Article 3 covers life, liberty, and security of person.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-036","question":"Which language is not one of the UN’s six official languages?","options":["Arabic","Chinese","Portuguese","Russian"],"answer":2,"explanation":"The six are Arabic, Chinese, English, French, Russian, and Spanish.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-037","question":"Which group lists all five permanent members of the UN Security Council?","options":["China, France, Russia, United Kingdom, United States","China, India, Japan, Germany, Brazil","France, Germany, Italy, Canada, Japan","United States, Mexico, Brazil, Argentina, Chile"],"answer":0,"explanation":"The five permanent members are commonly called the P5.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-038","question":"How long is a typical term for an elected non-permanent UNSC member?","options":["One year","Two years","Four years","Six years"],"answer":1,"explanation":"Elected non-permanent members serve two-year terms.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-039","question":"Which UN agency is most directly associated with agriculture and food security?","options":["FAO","UNHCR","UNICEF","UNESCO"],"answer":0,"explanation":"FAO works on food and agriculture.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-040","question":"A question about refugees and displaced people most directly points to:","options":["UNHCR","WHO","WTO","UNEP"],"answer":0,"explanation":"UNHCR is the UN refugee agency.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-041","question":"Which organization leads international public health coordination?","options":["WHO","FAO","IMF","NATO"],"answer":0,"explanation":"The World Health Organization coordinates international public health work.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-042","question":"Which UN agency has a mandate centered on children’s welfare?","options":["UNICEF","UNDP","UNEP","WTO"],"answer":0,"explanation":"UNICEF supports children’s rights, health, education, and welfare.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-043","question":"Education, science, and cultural cooperation most closely match:","options":["UNESCO","UNHCR","FAO","OPEC"],"answer":0,"explanation":"UNESCO works across education, science, and culture.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-044","question":"Which UN body focuses on environmental issues?","options":["UNEP","UNICEF","IMF","UNHCR"],"answer":0,"explanation":"UNEP is the United Nations Environment Programme.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-045","question":"Which agency is most associated with development and poverty-reduction programmes?","options":["UNDP","NATO","OPEC","WTO"],"answer":0,"explanation":"UNDP supports development and poverty-reduction work.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-046","question":"How many Sustainable Development Goals are there, and what is their target year?","options":["12 by 2025","15 by 2040","17 by 2030","20 by 2050"],"answer":2,"explanation":"The 17 SDGs were adopted with a 2030 target.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-047","question":"According to the SDG Report 2025 cited in the study pack, what share of goals was on track?","options":["About 18%","About 38%","About 58%","About 88%"],"answer":0,"explanation":"The cited report says about 18% of SDGs are on track.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-048","question":"The study notes say global electricity access has reached approximately:","options":["51.7%","71.7%","81.7%","91.7%"],"answer":3,"explanation":"The notes cite 91.7% global electricity access.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-049","question":"NATO was founded in which year?","options":["1945","1947","1949","1955"],"answer":2,"explanation":"The North Atlantic Treaty was signed in 1949.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-050","question":"NATO Article 5 is the alliance’s principle of:","options":["Collective defense","A shared currency","Free movement of labor","A climate target"],"answer":0,"explanation":"Article 5 treats an armed attack on one member as an attack on all.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-051","question":"What is the core role of the World Trade Organization?","options":["Provide a framework for international trade rules","Coordinate global disease response","Set national interest rates","Run peacekeeping missions"],"answer":0,"explanation":"The WTO administers trade agreements and provides a forum for trade rules and disputes.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-052","question":"Which institution is most closely associated with monetary cooperation and balance-of-payments support?","options":["IMF","UNESCO","FAO","ASEAN Secretariat"],"answer":0,"explanation":"The International Monetary Fund supports monetary cooperation and financial stability.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-053","question":"The World Bank is best known for:","options":["Development financing and poverty reduction","Collective military defense","Managing global oil quotas","Electing the UN Secretary-General"],"answer":0,"explanation":"The World Bank finances development projects and poverty-reduction efforts.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-054","question":"Russia participates in OPEC+ but is not an OPEC member. What does this illustrate?","options":["OPEC+ includes cooperating non-OPEC producers","OPEC+ is a military alliance","OPEC+ is a UN court","OPEC+ is limited to ASEAN states"],"answer":0,"explanation":"OPEC+ brings OPEC members together with additional cooperating oil producers.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-055","question":"In global affairs, globalization most directly describes:","options":["Growing cross-border connections in trade, communication, finance, and culture","The end of all national borders","A single world government","The replacement of all local languages"],"answer":0,"explanation":"Globalization refers to increasing interdependence across borders.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-056","question":"An agreement negotiated by exactly two states is best described as:","options":["Bilateral","Multilateral","Supranational","Non-aligned"],"answer":0,"explanation":"Bilateral describes relations or agreements between two parties.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-057","question":"A multilateral agreement normally involves:","options":["Three or more states or parties","Exactly one state","Only private companies","Only local governments"],"answer":0,"explanation":"Multilateral cooperation involves multiple states or parties.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-058","question":"State sovereignty refers most directly to a state’s:","options":["Authority over its territory and domestic governance","Right to veto every international treaty","Control of all neighboring economies","Membership in the G7"],"answer":0,"explanation":"Sovereignty is a state’s authority over its territory and political affairs.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-059","question":"Economic sanctions are generally used to:","options":["Apply pressure through restrictions or penalties","Provide automatic military protection","Create an international court","Guarantee an election outcome"],"answer":0,"explanation":"Sanctions are restrictive measures intended to influence behavior.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-060","question":"Which example is closest to soft power?","options":["Attracting partners through culture, values, and diplomacy","Using armed force to seize territory","Blocking all sea routes with warships","Imposing a military occupation"],"answer":0,"explanation":"Soft power works through attraction and persuasion.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-061","question":"Which example is closest to hard power?","options":["Using military force or coercive economic pressure","Sharing cultural festivals","Offering student exchanges","Promoting a language abroad"],"answer":0,"explanation":"Hard power relies on force or coercion.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-062","question":"A person forced to flee but still inside their own country is usually called:","options":["An internally displaced person","A stateless diplomat","A migrant worker","A treaty observer"],"answer":0,"explanation":"An internally displaced person has not crossed an international border.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-063","question":"A ceasefire is an arrangement intended to:","options":["Pause or stop hostilities","Create a permanent trade union","Set the exchange rate","Admit a state to ASEAN"],"answer":0,"explanation":"A ceasefire is a cessation or pause in fighting.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-064","question":"The term détente describes:","options":["A reduction in political tension between states","An increase in tariffs","A permanent military occupation","The start of a global recession"],"answer":0,"explanation":"Détente means easing tensions, especially between rival states.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-065","question":"Climate-change mitigation focuses on:","options":["Reducing greenhouse-gas emissions or increasing removals","Preparing hospitals for a heatwave only","Moving an embassy to a new city","Expanding fossil-fuel use"],"answer":0,"explanation":"Mitigation addresses the causes of climate change.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-066","question":"Climate adaptation focuses on:","options":["Adjusting systems and communities to climate impacts","Increasing emissions to speed warming","Ending all international trade","Replacing the UN General Assembly"],"answer":0,"explanation":"Adaptation reduces vulnerability to climate effects.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-067","question":"El Niño is associated with unusually warm sea-surface temperatures in which region?","options":["Central and eastern tropical Pacific","North Atlantic near Greenland","Southern Ocean near Antarctica","Mediterranean Sea"],"answer":0,"explanation":"El Niño is a warming phase in the central and eastern equatorial Pacific.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-068","question":"Autonomous weapons raise a central policy question about:","options":["How much human control remains over target selection and force","Whether countries can have flags","How to set ASEAN chair order","Whether trade can cross borders"],"answer":0,"explanation":"A key concern is the degree of human control over critical weapon decisions.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-069","question":"Why is the Strait of Hormuz strategically important?","options":["It is a major chokepoint for global energy shipping","It connects the Atlantic and Pacific Oceans","It is the headquarters of the UN","It is the only land crossing into Europe"],"answer":0,"explanation":"A significant share of global oil and gas shipments passes through the strait.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"},{"id":"extra-070","question":"COP meetings are primarily associated with international negotiations on:","options":["Climate change","Global public health","International criminal law","Nuclear disarmament"],"answer":0,"explanation":"COP is the conference of parties under the UN climate framework.","source":"โจทย์เสริมที่เรียบเรียงจากชีทที่แนบ"}];
